(window.STORIES=window.STORIES||[]).push(...[{"n": 238, "l": "الجزء 212 | إجابة اسألة آية السيف", "u": "https://www.facebook.com/groups/710210019782034/permalink/837711583698543/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_واثنا_عشر\n#أحداث_السنة_التاسعة_من_الهجرة\n#إجابة_أسئلة_آية_السيف\nاتكلمنا المرة إللي فاتت عن المشركين ومنعهم من دخول المسجد الحرام وإن رسول الله ﷺ أعطاهم وقت معين وبعد كده إما يسلموا أو يقتلهم، جالنا سؤالين على الجزء إللي فات هنرد عليهم النهاردة إن شاء الله \n☆السؤال الأول بيقول:\nحاسة إني مش فاهمة أوي آية السيف، \nيعني أنا أعرف إن دين الإسلام دين عفو ورحمة ومش بيقاتل المشركين إلا بالشروط إللى انتِ قولتيها بس ما هو الوضع كان كده قبل نزول آية السيف،\nيعني إن المسلمين لا يقاتلوا غير بالشروط إللي قلناها\nإللي هي:\nاعتدوا على المسلمين بسَلْب أو نهب أو اغتصاب لحقوق المسلمين، \nأو بسبب منعهم للمسلمين من نشر الإسلام وإيصاله إلى غيرهم.\nفإيه الاختلاف، وكده الناس هتقول إزاي بنقول إن الإسلام دين رحمة وهو بيجبر الناس على الدخول في الإسلام بعد نزول آية السيف؟\nشوفوا،\nاحنا محتاجين نفرق بين أمرين:\nالأمر الأول هو زمن نزول آية السيف في عهد رسول الله ﷺ والزمن إللي بعده،\nآية السيف لما نزلت في عهد رسول الله ﷺ كانت بتقول إن أي مشرك من العرب إللي عاصروا رسول الله ﷺ هيبقى موجود في الجزيرة العربية لو مدخلش الإسلام هيُقتل؛ \nلأن زي ما قلنا المرة إللي فاتت إنهم لا يستحقوا إنهم يسكنوا فيها؛ لأن الأرض أرض الله، وهم أعداؤه المعارضون والمحاربون له ولرسوله،\nوهم يا جماعة أصلا كانوا محاربين لرسول الله ﷺ، يعني احنا شوفنا مشركي الجزيرة كلها كانوا بيحاربوا رسول الله ﷺ إزاي وفيهم إللي خان العهود وفيهم إللي كان مستني أي فرصة للقضاء على المسلمين،\nفالأصل أصلا إنهم معتدين ولو الإسلام مكنتش ظهرت قوته كانوا هيستمروا في حربهم وعنادهم واعتداءهم على المسلمين،\nفجاء الرد الحاسم من ربنا إنهم بعد كل الأحداث دي عاصروها وشافوها مع رسول الله ﷺ مينفعش يستمروا على الشرك، \nفقصادهم إما الدخول في الإسلام وإما القتل\nفالمشركين العرب في عهد رسول الله ﷺ لو لم يسلموا بمجرد انتهاء العهد بتاعهم المسلمين هيقتلوهم\nالأمر التاني هو بعد زمن رسول الله ﷺ، لو قلنا افتراضا يعني إن محدش من المشركين في الأرض اعتدى على المسلمين بسَلْب أو نهب أو اغتصاب لحقوقهم،\nلكن السبب التاني موجود أكيد، وهو إن المشركين هيمنعوا المسلمين من نشر الإسلام وهنا هيحصل القتال بين المسلمين وبين المشركين وده الواقع إللي حصل بعد موت رسول الله ﷺ،\nأمة الإسلام هي آخر الأمم ويجب عليها نشر الإسلام وتوصيله لكل الناس،\nلكن في مشركين لهم مصالح في إن رعاياهم يستمروا على الكفر والضلال فهنا المسلمين هيقاتلوا جيوش المشركين دول عشان يوصلوا الإسلام لعامة الناس،\nفالمشرك لا يُقتل لأنه مشرك فقط أبدا، لكن يُقتل لأنه يحارب دين الله،\nفسواء في زمن رسول الله ﷺ أو بعد زمن رسول الله ﷺ فآية السيف حكمها قائم بسبب الشروط إللي قلناها.\n◇طيب إيه الاختلاف قبل وبعد نزول آية السيف\nالاختلاف هو إن قبل نزول آية السيف كان ممكن يبقى بين رسول الله ﷺ وبين المشركين عهد وهدنة زي ما حصل في صلح الحديبية،\nلكن بعد نزول آية السيف مبقاش في عهود تانية تتعمل بين المسلمين وبين المشركين في عهد رسول الله ﷺ ، إللي عنده عهد فالعهد بتاعه لحد مدته، \nوإللي معندوش عهد آخر مدة السماح بتاعته لحد انتهاء الأشهر الحُرم بعد كده خلاص إما الإسلام وإما القتل؛ والكفر مُغلّظ في حق المشركين في عهد رسول الله ﷺ لأن رسول الله ﷺ نشأ بين أظهرهم، \nوالقرآن نزل بلغتهم، فالمعجزة في حقهم أظهر، لأنهم كانوا أعرف بمعانيه، ووجوه الفصاحة فيه،\nوكل مَن تغلظ كفره لا يُقبل منه إلا الإسلام أو السيف\n◇طيب إزاي بنقول إن الإسلام دين رحمة وهو بيجبر الناس على الدخول في الإسلام بعد نزول آية السيف؟\nهو الإسلام مش بيجبر الناس على الدخول فيه بعد نزول آية السيف، ربنا لما قال:\n\"فَاقْتُلُوا الْمُشْرِكِينَ\"\nمعناه اقتلوا المشركين الذين يحاربونكم سواء كانوا معتدين أو مانعين لنشر الإسلام؛\n لأن الأصل أن يكون الدين لله، وأن تكون كلمة الله هي العليا فأي حد يمنع نشر الإسلام يُقاتل،\nوأما مَن لم يكن من أهل الممانعة والمقاتلة، زي النساء والصبيان والراهب والشيخ الكبير والأعمى فلا يُقتلوا.\nفعامة المشركين الغير محاربين للمسلمين دول بيتعرض عليهم الإسلام والمسلمين بيعلموهم الدين،\nومفيش إنسان عاقل يعرف الإسلام حق المعرفة بدون تشويه أو تحريف إلا ويعرف إن هو دين الحق وبالتالي يتبع الإسلام؛ لأن هو دين الفطرة\nوعلى مر التاريخ لما كان عامة المشركين الغير محاربين بيعرفوا الإسلام حق المعرفة كانوا بيدخلوا في الإسلام مباشرة\n¤طيب خلونا نمشي على القول إللي بيقول إن إللي بيرفض الدخول في الإسلام من المشركين وجب جهاده حتى يدخل في الإسلام،\nوده قول فعلا لبعض أهل العلم واستدلوا على كلامهم بآية السيف وبحديث رسول الله ﷺ:\n\"أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَشْهَدُوا أَنْ لا إِلَهَ إِلا اللَّهُ ، وَأَنَّ\n مُحَمَّدًا رَسُولُ اللَّهِ، وَيُقِيمُوا الصَّلاةَ ، وَيُؤْتُوا الزَّكَاةَ ، \nفَإِذَا فَعَلُوا ذَلِكَ عَصَمُوا مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ إِلا بِحَقِّ الإِسْلامِ ، وَحِسَابُهُمْ عَلَى اللَّهِ\"\nوالمقصود بالناس في الحديث يعني المشركين،\nوالحديث ده مُجمع على صحته من كل أهل العلم قديما وحديثا.\nفإيه المشكلة يعني إن المسلمين يفرضوا الإسلام على المشركين بالقوة\nخلوني أسألكم سؤال، لو واحد فينا شاف إنسان عايز يشعل في نفسه النار وجاب الكبريت والجاز وهيولع في نفسه خلاص،\nهل من الرحمة إني أسيبه يولع في نفسه بحجة إنه عايز كده ولّا الرحمة هي إنه أمنعه من كده حتى ولو بالغصب؟\nطبعا الرحمة إني أمنعه بالقوة غصب عنه\nطيب ما هو لو الإسلام بيغصب المشركين بالقوة إنهم يدخلوا في الإسلام عشان يُنقذهم من الخلود النار مش هي ده عين الرحمة\nانتم متخيلين يا جماعة إن الكفار وهم بيعذبوا في نار جهنم هيقولوا لربنا:\n\"رَبّنَا أَخْرِجْنَا مِنْهَا فَإِنْ عُدْنَا فَإِنَّا ظَالِمُونَ\"\nمتخيلين الندم إللي هيكون فيه الكفار يوم القيامة وحسرتهم إنهم لم يتبعوا ما أنزل الله ولم يتبعوا رسول الله ﷺ:\n\"يَوْمَ تُقَلَّبُ وُجُوهُهُمْ فِي النَّارِ يَقُولُونَ يَا لَيْتَنَا أَطَعْنَا الله وَأَطَعْنَا الرَّسُولَا\"\nفاحنا لو غصبنا المشركين على الإسلام فاحنا بنعمل فيهم معروف أصلا هيشكرونا عليه يوم القيامة مش إننا بقى وحشين وبنفرض عليهم حاجة هم مش عايزينهم\nطيب شوفوا حديث رسول الله ﷺ:\nرأيت ناسا من أمتي يُساقون إلى الجنة في السلاسل كَرْهًا. قيل: يا رسول الله من هم؟ \nقال : \"قوم من العجم يسبِيهم المهاجرون فيدخلونهم في الإسلام مُكرهين \"\nيعني احنا أصلا أمنيتنا إننا ندخل الجنة، في ناس بقى هيكونوا متسلسلين وبيُساقوا بالسلاسل عشان يدخلوا الجنة غصب عنهم متخيلين\nوالناس دي هم الأسرى من الجيوش إللي أخذهم الصحابة في الفتوحات الإسلامية بالغصب ودخلوا في الإسلام بعد كده،\nفهل بعد كده نقول إن مش من الرحمة إن الإسلام يغصب المشركين على الدخول فيه\n◇ملحوظة:\n كل الكلام ده\n على المشركين فقط، أما المجوس وأهل الكتاب من اليهود والنصارى واسمهم أهل الذمة فلا يجوز إكراههم على الدخول في الإسلام ولا حربهم ماداموا بيدفعوا الجزية\n☆طيب لماذا يدفع المجوس الجزية مثل أهل الكتاب وهم يعبدون النار ولا يؤمنون بالله بعكس أهل الكتاب\nهو ده السؤال التاني معانا النهاردة\nالموضوع أصلا على خلاف بين العلماء، وأنا المرة إللي فاتت قلت لكم القول إللي يقول به أكثر أهل العلم عشان ميحصلش عندكم لخبطة \n◇فريق من العلماء قالوا إن الجزية تُؤخذ من كل كافر سواء من أهل الكتاب من اليهود والنصارى أو من غيرهم سواء إللي بيعبدوا النار أو إللي بيعبدوا الأصنام أو غيرهم.\n◇والقول التاني وهو الراجح وإللي عليه جمهور أهل العلم وهو إن الجزية تُؤخذ فقط من أهل الكتاب اليهود والنصارى بنص القرآن في قوله تعالى في سورة التوبة:\n\"قَاتِلُوا الَّذِينَ لَا يُؤْمِنُونَ بِاللَّهِ وَلَا بِالْيَوْمِ الْآخِرِ وَلَا يُحَرِّمُونَ مَا حَرَّمَ اللَّهُ وَرَسُولُهُ وَلَا يَدِينُونَ دِينَ الْحَقِّ مِنَ الَّذِينَ أُوتُوا الْكِتَابَ حَتَّى يُعْطُوا الْجِزْيَةَ عَنْ يَدٍ وَهُمْ صَاغِرُونَ\"\n¤تفسير الآية:\nربنا بيأمر المسلمين إنهم يقاتلوا أهل الكتاب من اليهود والنصارى حتى يُسلموا أو يدفعوا الجزية وهم صاغرين، يعني خاضعين لأحكام الإسلام وسيادته؛ \nلأن أهل الذمة إذا دفعوا الجزية وعاشوا مع المسلمين في بلادهم فهم يُحكموا بشريعة الإسلام إذا اختصموا مع المسلمين،\nأما أمورهم الخاصة في بيوتهم ومعابدهم فهم يحكموا فيها بشريعتهم،\nوربنا لما قال عن أهل الكتاب إنهم لا يؤمنوا بالله ولا باليوم الآخر مع إنهم معترفين بوجود الله وإن في يوم آخر المقصود إنهم لا يؤمنوا بالله واليوم الآخر على الوجه إللي ربنا يريده،\nيعني اليهود معترفين بوجود الله وإنه الخالق والرازق و....و....\nلكن بيقولوا لعنهم الله إن يد الله مغلولة،\nوالنصارى بيقولوا أن لله ولد أو أن الله هو المسيح ابن مريم،\nفهم لا يؤمنون بالله حق الإيمان فعشان كده ربنا قال عنهم لا يؤمنون بالله،\nوبالنسبة لليوم الآخر فاليهود كانوا بيقولوا لرسول الله ﷺ إنهم هيدخلوا النار يتعذبوا فيها شوية وبعدين أمة الإسلام يخلفوهم في النار، \nيعني هم يطلعوا والمسلمين يدخلوا فيها ويخلّدوا في النار،\nفرسول الله ﷺ رد عليهم وقال لهم: والله لا نخلُفكم فيها أبدا\nوالمقصود ب《 وَلَا يُحَرِّمُونَ مَا حَرَّمَ اللَّهُ وَرَسُولُهُ وَلَا يَدِينُونَ دِينَ الْحَقِّ 》\nيعني إنهم يستحلّوا الخمر وأكل لحم الخنزير وغيرها من المُحرمات، ولا يتبعوا دين الحق إللي هو الإسلام؛\nلأنهم إما على دين محرف أو دين منسوخ بمجيء الإسلام.\nبالنسبة بقى لدفع المجوس للجزية فلأن رسول الله ﷺ أخذ الجزية من مجوس منطقة هَجَر فبقى تشريع إن المجوس يدفعوا الجزية زيهم زي أهل الكتاب،\nطيب اشمعنى المجوس بالذات إللي يدفعوا الجزية ويكونوا ويكونوا زي أهل الكتاب\n الله أعلم\nده تشريع زي باقي تشريعات الإسلام، وزي ما قلنا الموضوع أصلا على خلاف بين العلماء،\nلكن في قول 《ضعيف》عن ابن عباس بيقول إن المجوس كانوا أصلا أهل كتاب فلما مات نبيهم كتب لهم إبليس المجوسية،\nيعني إبليس خلّى المجوسية مكان دين نبيهم فبقوا مجوس بإغواء إبليس لهم بعد ما كانوا على دين نبيهم،\nفكده يدخلوا مع أهل الكتاب في الحكم،\n لكن زي ما قلت لكم القول ده ضعيف، فالله أعلم إيه السبب إن المجوس يكونوا من أهل الذمة يؤخذ منهم الجزية زي أهل الكتاب\nخلاصة الكلام بقى:\n◇أجمع أهل العلم إن الجزية تُؤخذ من اليهود والنصارى والمجوس قولا واحدا.\nولما ينزل عيسى عليه السلام في آخر الزمان لن يقبل من أهل الكتاب إلا الإسلام أو القتل ومش هيبقى في جزية،\nواحنا شرحنا الموضوع بالتفصيل في علامات الساعة.\n◇اختلف أهل العلم هل تُؤخذ الجزية من المشركين زي عبدة الأوثان وغيرهم ولّا لأ،\nفريق قال:\n☆لا تُؤخذ الجزية من المشركين من أهل الأوثان ومن شابههم فيكون إما الإسلام وإما القتل.\n☆فريق تاني قال:\nمفيش مشكلة أن تُؤخذ الجزية من كل المشركين ما عدا المشركين العرب فإن العرب لا يُقرُّون على الجزية؛ لأن رسول الله ﷺ لم يقرّهم على الجزية،\nفالمشركين غير العرب من الأعاجم مفيش مشكلة إنهم يدفعوا الجزية إذا قبلوا بها، حتى ولو مكنوش  يهود ولا نصارى ولا مجوس،\nفالموضوع ساعتها يرجع لولي الأمر، يعني يشوف المصلحة الشرعية فين، فلو شاف إن المصلحة هي قبول منهم الجزية أقرّهم على الجزية، \nولو شاف إن المصلحة الشرعية في  قتالهم حتى يسلموا قاتلهم\n◇أخيرا:\nأحكام أهل الكتاب من اليهود والنصارى تختلف عن أحكام غيرهم من أهل الشرك،\nيعني أهل الكتاب من اليهود والنصارى كفار مشركين، لا يدخلوا المسجد الحرام زيهم زي المشركين عَبدة الأوثان وغيرهم،\nلكن يجوز للمسلم أن يتزوج من المرأة اليهودية أو النصرانية بشروط.\nأما النساء المشركات إللي بتعبد الأصنام أو المجوسيات إللي بيعبدوا النار وغيرهم من المشركين فلا يجوز للمسلم الزواج منهن،\nويجوز للمسلم الأكل من ذبائح أهل الكتاب، أما ذبائح المشركين من المجوس وعبدة الأوثان وغيرها فلا يجوز الأكل منها.\n♡معلش يا جماعة الموضوع فيه تفريعات كتير حاولت ألخصها لكم بطريقة بسيطة، فاعذروني لو الكلام يتوّه شوية"}, {"n": 239, "l": "الجزء 213 | الجزية في  الإسلام", "u": "https://www.facebook.com/groups/710210019782034/permalink/837712117031823/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وثلاثة_عشر\n#أحداث_السنة_التاسعة_من_الهجرة\n#الجزية_في_الإسلام\nاتكلمنا عن نزول الأمر من الله بمنع المشركين من دخول المسجد الحرام،\nقال تعالى في سورة التوبة:\n\"يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْمُشْرِكُونَ نَجَسٌ فَلَا يَقْرَبُوا الْمَسْجِدَ الْحَرَامَ بَعْدَ عَامِهِمْ هَٰذَا\"\nيعني أهل الشرك مُعتقدهم نجس، يعني دينهم إللي بيعتقدوه نجس، والنجاسة المقصودة في الآية هي نجاسة معنوية،\nوليس المقصود النجاسة الحسية، يعني مثلا لو مسلم سلم على واحد مشرك مش مطلوب منه إنه يغسل إيده بعد ما سلم عليه، \nسواء كان المشرك ده على النصرانية أو اليهودية أو يعبد الأصنام\nفلأن أهل الشرك معتقدهم نجس فلا يقربوا المسجد الحرام بعد العام إللي نزلت فيه الآية دي،\nوطبعا العكس مع المسلمين،\nيعني المسلم طاهر حتى لو أصابته جنابة مثلا، هو فقط مطلوب منه يغتسل لرفع الجنابة،\nوهو طاهر حتى لو أصابت ثوبه أو بدنه نجاسة، لكن يجب عليه غسل النجاسة دي\nوالدليل على إن المسلم أو المؤمن لا ينجس موقف حصل مع أبو هريرة رضي الله عنه بيقول:\nأنَّ النبيَّ ﷺ لَقِيَهُ في بَعْضِ طَرِيقِ المَدِينَةِ وهو جُنُبٌ، فَانْخَنَسْتُ منه، فَذَهَبَ فَاغْتَسَلَ ثُمَّ جَاءَ.\n فَقالَ: أيْنَ كُنْتَ يا أبَا هُرَيْرَةَ؟\n قالَ: كُنْتُ جُنُبًا، فَكَرِهْتُ أنْ أُجَالِسَكَ وأَنَا علَى غيرِ طَهَارَةٍ، فَقالَ:\n \"سُبْحَانَ اللَّهِ، إنَّ المُسْلِمَ لا يَنْجُس\".\nيعني أبو هريرة كان ماشي في بعض طُرق المدينة وكان على جنابة، \nفقابل رسول الله ﷺ في الطريق فلما شافه أبو هريرة ورسول الله ﷺ نفسه شاف أبو هريرة فالمفروض في الموقف ده إن أبو هريرة يسلم على رسول الله ﷺ، \nلكن ده محصلش، أبو هريرة رجع من غير يسلم على رسول الله ﷺ أو يكلمه، وده معنى:\n《فانْخَنَسْتُ منه》،\nفراح أبو هريرة واغتسل وبعدين رجع تاني لرسول الله ﷺ،\nفسأله رسول الله ﷺ كنت فين، فقال له أبو هريرة إنه كان على جنابة فكَرِه إنه يقعد مع رسول الله ﷺ وهو غير طاهر،\nفرسول الله ﷺ تعجب من تفكير أبو هريرة وقال له المسلم لا ينجس، يعني المسلم مش قَذِر\nالعلماء اختلفوا بقى في معنى المسجد الحرام المقصود في الآية،\nيعني هل المقصود بالمسجد الحرام المسجد إللي فيه الكعبة فقط؟\nولّا المقصود بالمسجد الحرام هو مكة كلها ولّا المقصود عموم منطقة الحرم إللي متحددة بأعلام معينة\nقال بعض العلماء إن المقصود بالمسجد الحرام هو منطقة الحرم بصفة عامة مش بس المسجد إللي فيه الكعبة، وده هو القول الراجح،\nحتى دلوقتي في علامات في مكة قبل منطقة الحرم مكتوب عليها يُمنع دخول غير المسلمين،\nوفي علماء قالوا إن المقصود بالمسجد الحرام هو المسجد نفسه إللي فيه الكعبة،\nلكن زي ما قلنا القول الأول هو القول الراجح.\n☆ملحوظة:\nاحنا قلنا إن رسول الله ﷺ في آخر حياته أمر بإخراج كل الناس إللي على غير ملة الإسلام من جزيرة العرب،\nفمينفعش أصلا دخول غير المسلمين لمكة بصفة عامة،\nبس احنا بنشرح زمن نزول الآية والمقصود منها إيه\nبعد ما نزلت آية منع المشركين من دخول المسجد الحرام المسلمين في مكة شافوا إن الموضوع شاق وصعب عليهم\n \n☆ليه؟ \nاحنا عارفين إن مكة قائمة على التجارة، وبما إن فيها البيت الحرام فكل العرب بيأتوا لمكة، فهي قِبلة العرب،\nوبالتالي هتتوفر في مكة كل أنواع البضاعة من كل مكان،\nفدلوقتي المشركين إللي كانوا بييجوا من كل مكان اتمنعوا من إنهم ييجوا، وده طبعا هيأثر تأثير سلبي كبير جدا على التجارة في مكة وعلى المسلمين،\nوالناس قالوا خلاص كده مش هيبقى في أسواق وهتهلك التجارة \nفربنا أنزل:\n\"وَإِنْ خِفْتُمْ عَيْلَةً فَسَوْفَ يُغْنِيكُمُ اللَّهُ مِنْ فَضْلِهِ إِنْ شَاءَ ۚ إِنَّ اللَّهَ عَلِيمٌ حَكِيمٌ\"\nيعني ربنا بيقول للمسلمين لو خفتم من الفقر بسبب انقطاع تجارتكم مع المشركين نتيجة لمنعهم من دخول الحرم؛ فربنا هو إللي هيغنيكم من فضله إذا شاء سبحانه،\nوربنا هنا ربط الغنى بالمشيئة؛ لأن ممكن الغِنى يكون فيه ضرر عليهم،\nفقال لهم لو الغِنى فيه خير لكم سأغنيكم ولو فيه ضرر لن يفتح عليكم في الغِنى،\nفهو الحكيم سبحانه فلا يكون شيء في كونه إلا بعلمه وبحكمته\n☆نقف هنا وقفة،\nالآية مش خاصة فقط بالمسلمين في مكة في زمن رسول الله ﷺ، الآية دي هي رسالة لكل واحد فينا إننا نهجر ونترك ما نهى الله عنه،\nوإللي خايف على مصلحته ورزقه ربنا هيغنيه من فضله بحوله وقوته؛ لأن الرزق مش بالشطارة ولا الاجتهاد ولكنه فضل من الله قسمه بين العباد،\nربنا بيقول:\n\"نَحْنُ قَسَمْنَا بَيْنَهُمْ مَعِيشَتَهُمْ فِي الْحَيَاةِ الدُّنْيَا\"\nفلما يكون واحد بيشتغل في بيع الخمور مثلا ونقول له إن ده حرام ولازم يشتغل شغلانة تانية حلال مينفعش يقول وأنا هشتغل إيه، ما هو مفيش شغل...مفيش بديل، \nهنا لازم إنه يترك طريقة الكسب الحرام دي وهو سبحانه هيرزقه من الحلال،\nوزي برده إللي بيتعامل بالربا وشغله كله بالربا بحجة إن مفيش طريقة تانية لكسب الرزق،\nوتلاقيه يروح يدور على فتاوى تبيح له التعامل بالربا، وممكن يجادل بقى ويتطاول على الشرع:\nهو ليه كذا حرام...الكلام مش منطقي...أصل أنا مش مقتنع...طب إيه العِلة يعني..إلى آخره من الكلام إللي بنسمعه من الناس\nفخلاصة الكلام:\nإن خفتم أيها المؤمنون فقرا بسبب التزام أحكام الله، فسيغنيكم الله تعالى من فضله\n◇طيب نفرض إن ربنا لم يعطِ الإنسان بعد ما ترك الحرام\nيبقى ده من الابتلاء والتمحيص\nفلازم الإنسان يكون عنده صبر ويأخذ بالأسباب الصحيحة ويكون عنده حسن توكل على الله،\nولازم نفهم إن لا العطاء دليل على المحبة ولا المنع دليل على الكراهية، \nلكن دي حكمة ربنا في تدبير الأمور، وهو ربط الغنى بالمشيئة زي ما قلنا عشان يعرفنا إنه هيعمل لنا الأصلح لنا \nبعد آية إنما المشركون نجس جاءت الآية إللي بعدها تقول للمؤمنين على الطريق إللي هيعوضهم عن تجارتهم مع المشركين في مكة، قال تعالى:\n\"قَاتِلُوا الَّذِينَ لَا يُؤْمِنُونَ بِاللَّهِ وَلَا بِالْيَوْمِ الْآخِرِ وَلَا يُحَرِّمُونَ مَا حَرَّمَ اللَّهُ وَرَسُولُهُ وَلَا يَدِينُونَ دِينَ الْحَقِّ مِنَ الَّذِينَ أُوتُوا الْكِتَابَ حَتَّى يُعْطُوا الْجِزْيَةَ عَنْ يَدٍ وَهُمْ صَاغِرُونَ\"\nاحنا شرحنا الآية المرة إللي فاتت بالتفصيل ممكن ترجعوا لها،\nلكن إللي هنتكلم عنه النهاردة هي الجزية، يعني إيه جزية ومقدارها أد إيه وواجبة على مين\n◇أولا معنى الجزية:\nالجزية هي ضريبة سنوية على الرؤوس، يعني مقدار معين من المال بيدفعه أهل الذمة سواء اليهود أو النصارى أو المجوس للمسلمين.\n◇تُفرض الجزية على:\n على الرجال الأحرار البالغين العقلاء الأصحاء القادرين، يعني من الآخر إللي عندهم القدرة على القتال في الحرب هم دول إللي تُفرض عليهم الجزية،\nوده على حسَب ثرواتهم،\nأما الفقراء فمُعفَون منها إعفاء تامًّا، يعني الفقراء لا يدفعون الجزية.\nولا تجب الجزية على امرأة ولا صبي ولا مجنون ولا عَبد ولا مريض مرضًا غالبًا، ولا راهب.\n◇مقدار الجزية:\nالجزية ملهاش حد معين حدٌّ معين، لكن أقلها دينار، يعني 12 درهم، فإمام المسلمين هو إللي يحددها مع مراعاة طاقات الدافعين ولا يُرهِقهم، وعليه أن يراعي المصلحة العامة للأمة،\nوعمر بن الخطاب رضي الله عنه جعل الجزية 48 درهمًا على الأغنياء،\nوعلى المتوسطين في الغِنى 24 درهم، وعلى الطبقة الدُّنيا من الأغنياء 12 درهمًا،\nوالدرهم زي ما قلنا قبل كده يساوي ثلاثة جرامات من الفضة، \nفالجزية دي بيدفعها الشخص المقتدر وعنده فلوس فقط، أما الفقير فلا\n◇طيب إيه الحكمة أو الهدف من دفع الجزية\n¤أولا:\nإظهار سيادة الدولة الإسلامية وإعلان خضوع وانقياد أهل الذمة لحكم المسلمين، وبيان عزة الإسلام وأهله، وصَغار وذِلة الكفر وأهله، وده ظاهر الآية: \n\"حتَّى يُعْطُوا الجِزْيةَ عَنْ يَدٍ وهم صَاغِرُون\"\nزي ما شرحناها المرة إللي فاتت\n¤ثانيا:\nالجزية وسيلة تساعد على ترك أهل الذّمّة لدينهم ودخولهم إلى الإسلام\nإزاي\nما هو الكافر لو اتقتل خلاص ملوش أي فرصة وهيبقى خالد في نار جهنم،\nلكن لو دفع مبلغ من المال وهو حاسس بالذل بسبب الكفر إللي هو فيه وإللي اضطره يدفع المال ده وهو ذليل وكمان هيعيش وسط المسلمين ويتعرف على الإسلام أكتر فساعتها احتمال كبير يدخل في الإسلام؛ \nلأن الإسلام دين الفطرة ولا يتصادم مع العقل بعكس أي دين تاني،\nفهنا فرصة نجاته من الخلود في النار أكبر\nوالغاية والمطلوب مش إذلال الناس ولا قتالهم ولكن الغاية هي إنقاذهم من الخلود في نار جهنم\nفالجزية وسيلة لحفظ أهل الذمة وعصمة دمائهم وأموالهم والتوقف عن قتالهم، وإِفساح الفرصة لهم ليتعرفوا على الإسلام ويدخلوا فيه\n¤ثالثا:\nالجزية مصدر من مصادر الدولة الماليّة، تستعين به الدّولة الإسلاميّة في الإنفاق على المصالح والخدمات والمرافق العامّة والحاجات الأساسيّة للدولة، زي الأمن والتعليم والصحة والطرق والمساكن وغيرها،\nوطبعا الخدمات دي هيستفيد بيها المسلمين وكمان أهل الذمة إللي عايشين على أراضي المسلمين،\nوكمان الجزية دي مقابل حماية المسلمين لأرواح أهل الذمة وأموالهم،\nفيجب على المسلمين في مقابل أخذهم للجزية إنهم يوفروا الحماية لأهل الذّمّة ويمنعوا أي حد عايز يعتدي عليهم،\nولو أُخذ منهم أسرى يجب عليهم إنهم يبذلوا جهدهم في استرداد الأسرى واستعادة أموالهم إذا أُخذت ظلما\n☆ملحوظة مهمة:\nالجزية هي أقل من الزكاة المفروضة على المسلمين، يعني مقدار الزكاة على الأموال مثلا هو 2.5%\nعلى حسب المبلغ إللي موجود مع المسلم، بعكس الجزية إللي لها شروط معينة ومبلغ أقل من كده وطبعا هي أقل من الضرائب المفروضة على الناس بصفة عامة،\nيعني ملوك الروم كانوا بياخدوا من الفلاحين نصف انتاجهم، وساعات ياخدوا أموالهم كلها،\nفالجزية أصلا في صالح الكفار ومفيش فيها أي ظلم لهم\nوطبعا لو عملنا بحث سريع وشوفنا كمية الضرائب إللي الناس بتدفعها ومنهم أهل الذمة هنشوف أد إيه شريعة الإسلام أنصفت أهل الذمة وحفظت لهم حقوقهم بدون ظلم،\nوخصوصا إن الضرائب دي مفروضة على الكل رجال ونساء وكبار السن وغيرهم بدون مراعاة لظروفهم، بعكس الجزية إللي لها شروط معينة، لو مش موجود هتسقط عنهم\n◇طيب سؤال،\nإزاي الإسلام يفرض على المسلمين الزكاة إللي هي مقدارها أكثر من الجزية إللي بيدفعها الكفار،\nيعني ليه المسلمين يدفعوا أموال أكثر من الكفار،\nمش كده يبقى في ظلم للمسلمين الموحدين\nبكل بساطة لأنهم كفار غير مسلمين ودي دولة إسلامية\nيعني مش عدل أبدا إن الإسلام يفرض على الكافر إنه يدفع أموال أكثر عشان يدعم الدولة الإسلامية،\nلكن العدل إنه يدفع مبلغ بسيط مقابل توفير الحماية والأمن له،\nأما بالنسبة للمسلمين فأموال الزكاة إللي بيدفعوها تستخدم في إقامة الدولة الإسلامية وفي دعم إخوانهم الفقراء المسلمين،\nفطبيعي جدا إن إللي بيكون عايش في بيت ملكه يكون هو أكتر واحد بيدفع أموال عشان يرمم البيت ويحافظ عليه من الخراب\n☆عندنا سؤال كمان،\nإيه نظام أهل الذمة إللي عايشين معانا في واقعنا الحاضر، مش المفروض يدفعوا جزية زي ما ربنا أمر\nشوفوا،\nالجزية كحكم شرعي موجود ويجب تطبيقه، لكن تطبيق الحكم ده بيكون على حسب مقدرة المسلمين وقوتهم،\nيعني حكم الجزية لم يُفرض إلا في السنة التاسعة من الهجرة، بعد ما بقت القوة للإسلام والمسلمين،\nوظهر الإسلام وبقت الغلبة والتمكين لدين الإسلام\nفتطبيق الأحكام المُعتمدة على قوة المسلمين وغلبتهم؛ مش هيقدروا يطبقوها وهم في حالة ضعف وذل،\nفبسبب واقع المسلمين دلوقتي من الضعف والذل والهوان خلى من المستحيل فرض الجزية على أهل الذمة،\nده المسلمين مش عارفين يستعيدوا المسجد الأقصى من اليهود، هيفرضوا عليهم جزية إزاي بقى\nوالمسلمين حاليا مش عارفين حتى يطبقوا الشرعية على نفسهم في بلادهم، إزاي هيطبقوها على غيرهم\nفزي ما قتال المشركين إللي ربنا أمر بيه في آية السيف مرهون بقدرة المسلمين، كذلك فرض الجزية على أهل الذمة مرهون بقدرة المسلمين على تطبيق الحكم ده\nكده يبقى احنا خلصنا أهم الأحداث إللي حصلت في السنة التاسعة من الهجرة،\nقبل ما ندخل في أحداث السنة العاشرة من الهجرة،\nهنتكلم المرة الجاية إن شاء الله عن بعض مواقف رسول الله ﷺ مع الأطفال، وبعض مواقفه مع الشباب، وبعض مواقفه مع الحيوانات\nمصادر جزء النهاردة في التعليقات"}, {"n": 240, "l": "الجزء 214 | بعض مواقف رسول الله مع الأطفال", "u": "https://www.facebook.com/groups/710210019782034/permalink/837712297031805/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وأربعة_عشر\n#أحداث_السنة_التاسعة_من_الهجرة\n#بعض_مواقف_رسول_الله_مع_الأطفال\nقبل ما ندخل في جزء النهاردة خلوني أفكركم إن من أهم الأحداث إللي حصلت في السنة التاسعة من الهجرة مجيء تميم الداري،\nوتميم الداري هو إللي قابل المسيح الدجال على الجزيرة المهجورة، واحنا اتكلمنا عنه بالتفصيل لما كنا بنتكلم عن علامات الساعة الكبرى\nهنتكلم النهاردة بقى عن بعض مواقف رسول الله ﷺ مع الأطفال،\nرسول الله ﷺ بصفة عامة كان بيحب الأطفال وكان رحيم بيهم وكان لما بيعدي على أطفال وهم بيلعبوا كان بيمسح على رؤسهم،\nوكنا قلنا في الجزء الثامن والثمانين إنه كان بيرش وجه الواحد منهم بالمية ويضحك،\nوكان بيهزر مع واحد تاني ويقول له: \"يا ذا الأذنين\" ، كإنها حاجة غريبة وهي حاجة عادية أصلا، لأن كل واحد عنده أذنين فكانوا فبيضحكوا كلهم\nوكان بيحب يفرّحهم باللعب المفيد معاهم، فكان بيوقف بعض الأطفال صفوف ويقول لهم: \nتسابقوا وإللي يوصل لي الأول له مكافأة كذا وكذا!\nفيستبقون إليه، فيقعون على ظهره وصدره، ويتمرغون فيه  فيقبّلهم ويحضنهم ﷺ \nفكان الأطفال بيحبوا رسول الله ﷺ جدا، وكان لما رسول الله ﷺ يغيب عن المدينة لأي سبب كان أول مَن يستقبله هم الأطفال\nمفيش ولا مرة خلال الثلاثة وعشرين سنة من بعثته ﷺ وحتى قبل البعثة؛ سمعنا عنه ﷺ إنه ضرب أو عنّف طفل،\nده بالعكس كمان؛\nيعني رسول الله ﷺ خاتم الأنبياء والمرسلين... القائد السياسي...القائد العسكري...الإمام...على عظيم شغله ومسؤولياته الكبيرة إلا أنه كان يلاطف أطفال الصحابة، ويدخل السرور عليهم\n♡من المواقف دي موقف بيحكيه أنس بن مالك رضي الله عنه، بيقول:\n\"كان رسول الله ﷺ يدخُلُ علينا ولي أخٌ صغيرٌ يُكنَى أبا عميرٍ، وكان له نُغَرٌ يلعبُ به، فمات...\"\nيعني أنس بيقول إن رسول الله ﷺ كان بيزورهم كتير في البيت، وكان عنده أخ صغير كنيته أبا عمير،\nوكان عنده طائر شَبه العصفور بيلعب بيه، وكان رسول الله ﷺ لما بيروح في بيت أنس كان بيلاعب ويلاطف أبا عمير،\n\"فدخل عليه النبي ﷺ ذات يوم فرآه حزينًا، فقال: ما شأنه؟ فقالوا: مات نغرُهُ.\nفقال ﷺ: يا أبا عُميرٍ! ما فعل النُّغيرُ؟!\nيعني في مرة دخل عندهم رسول الله ﷺ فلقى أبا عمير قاعد حزين،\nفسألهم عن سبب حزنه قالوا له إن الطائر بتاعه إللي كان بيلعب بيه مات،\nفرسول الله ﷺ عشان يصرف عنه الحزن قعد يمازحه ويلاطفه ويقوله: يا أبا عمير! ما فعل النغير؟!\n☆فرسول الله ﷺ بيعلمنا هنا إننا نحترم مشاعر الأطفال الصغار، \nونخفف عنهم إللي ممكن يحصل لهم من مصائب حتى لو كانت من وجهة نظرنا حاجة عادية ومش مستاهلة،\nولو تاخدوا بالكم رسول الله ﷺ انتبه لتغير وجه الطفل فعرف إن في حاجة مش طبيعية، وإن دي مش عادته وبعدين بدأ يسأل عن السبب،\nفالاهتمام بالأطفال إللي ممكن في مرحلة من المراحل ميكونوش مستوعبين إللي بيحصل حواليهم؛ مطلوب،\nفما بالكم كمان بالكبار\nفالعلماء استنبطوا من الحديث ده فائدة:\n《إن من دوام المحبة والمودة بين الأصدقاء، السؤال عنهم ومعرفة أخبارهم،\nوإن مِن الأدبِ الحَسَنِ سُؤالَ الأخِ لأخيه عن سَببِ حُزنِه ومُواساتَه، والتَّلطُّفَ بالصَّديقِ صَغيرًا كان أو كبيرًا، والسُّؤالَ عن حالِه》\nموقف تاني حصل مع أنس بن مالك نفسه رضي الله عنه،\nلكن قبل ما نعرف الموقف خلونا نعرف كده سريعا مين هو أنس بن مالك\nهو أنس بن مالك بن النّضر، اتولد قبل الهجرة بعشر سنوات،\nوفي رواية ثماني سنوات،\nيعني لما رسول الله ﷺ هاجر للمدينة كان عمره عشر سنوات، أو ثمانية على اختلاف الروايات،\nوأمه الرّميْصاء أم حرام واسمها مَلِيكة بنت مِلحان، وهي صاحبة أغلى مهر في الإسلام لما تزوجت أبو طلحة الأنصاري،\nوهي إللي كانت معاها خنجر في غزوة حنين وثبتت مع رسول الله ﷺ لما الناس فروا من حوله،\nوخال أنس هو حرام بن مِلحان إللي استشهد في حادثة بئر معونة،\nوعم أنس بن مالك هو أنس بن النضر إللي استشهد في غزوة أحد، وكان بيقول قبل ما يُقتل:\n\"إني لأجد ريح الجنة دون أحد\"\nوعمة أنس هي الرُّبيّع بنت النضر إللي ابنها حارثة استشهد قبل بداية معركة بدر ورسول الله ﷺ بشرها بإن ابنها أصاب الفردوس الأعلى\nيعني هو من عائلة كلها أبطال\nبعد ما رسول الله ﷺ هاجر للمدينة، أخذته أمه أم سُليْم لرسول الله ﷺ وكان عمر أنس ساعتها عشر سنوات زي ما قلنا وقالت له:\n\"يا رسول الله، لم يبقَ رجل ولا امرأة مِن الأنصار إلا وقد أتحفك بتحفة، وإنِّي لا أقدر على ما أُتحفك به إلا ابني هذا، فخُذه، فليَخدُمك ما بدا لك\"\nيعني بعد ما رسول الله ﷺ هاجر للمدينة الصحابة بقوا يرسلوا له الهدايا، فأم سليم مكنش عندها حاجة تهديها لرسول الله ﷺ، فقالت له ياخد ابنها أنس ويكون خادم له، سنة... سنتين... زي ما هو عايز،\nفاتعرَف أنس على مرّ القرون بإنه خادم رسول الله ﷺ، وكان بيفخر بإنه معروف بإنه خادم رسول الله ﷺ، حتى إنه قال بعد موت رسول الله ﷺ:\n\"إنِّي لأرجو أن ألقى رسولَ الله ﷺ في يوم القيامة، فأقول له: يا رسول الله، هذا خُوَيدمك أنس\"\nوطبعا بسبب إن أنس رضي الله عنه كان بيخدم رسول الله ﷺ فكان مُلازم له، \nوده أدى إلى إن أنس ينقل للأمة أحداث وأفعال وأقوال لرسول الله ﷺ محدش اطلع عليها غيره،\nوأنس بيحكي عن نفسه بيقول:\n\"خدمتُ رسولَ اللهِ ﷺ عشرَ سنينَ، فما قال لي أُفٍّ قطُّ، وما قال لي لشيٍء صنعتُه:\nلِمَ صنعتَه، ولا لشيٍء تركتُه: لِمَ تركتَه،\nوما أمَرَني بأمرٍ فتوانيتُ عنه أو ضيَّعتُه، فلامَني، فإنْ لامني أحدٌ مِن أهل بيتِه إلَّا قال: دعُوه، فلو قُدِّرَ -أو قال: لو قُضِيَ- أن يكونَ كان\"\nيعني أنس بيحكي وبيقول إن خلال العشر سنين إللي خدم فيهم رسول الله ﷺ، محصلش ولا مرة واحدة إن رسول الله ﷺ اتضايق من حاجة أنس عملها فقاله أف،\nولو عمل حاجة من نفسه كده من غير ما رسول الله ﷺ يأمره بيها مكنش بيعاتبه ولا بيقوله ليه عملت كذا،\nولو أنس ترك حاجة كان مأمور بيها مكنش رسول الله ﷺ بيعاتبه ولا يلوم عليه انت معملتش كذا ليه،\nولو أمره بحاجة وتأخر فيها أو معملهاش مكنش بيلومه، ولو حد من أهله ﷺ لام أنس كان رسول الله ﷺ بيقول لهم سيبوه، لو ربنا كان مقدر إن الأمر ده يحصل أو يتعمل كان اتعمل\nوطبعا المقصود هنا أمور الخدمة مش التكاليف الشرعية\n♡من المواقف بقى إللي حصلت مع أنس رضي الله عنه بيقول:\nكانَ رَسولُ اللهِ ﷺ مِن أَحْسَنِ النَّاسِ خُلُقًا، فأرْسَلَنِي يَوْمًا لِحَاجَةٍ، فَقُلتُ: وَاللَّهِ لا أَذْهَبُ، وفي نَفْسِي أَنْ أَذْهَبَ لِما أَمَرَنِي به نَبِيُّ اللهِ ﷺ....\"\nيعني أنس بيقول عن رسول الله ﷺ إنه كان من أحسن الناس خُلقا، وبيستدل على كلامه ده بالموقف إللي حصل معاه، فبيقول إن رسول الله ﷺ أمره إنه يروح مكان معين عشان عايز منه حاجة،\nفأنس عاند مع رسول الله ﷺ وحلف بالله إنه مش هيروح\nمع إنه من جوّاه ناوي يروح، بس هو أظهر لرسول الله ﷺ إنه بيخالف أمره ومش هيروح،\nوأنس هنا كان صغير في السن رضي الله عنه، كان رايح لرسول الله ﷺ وهو عنده ٨ أو ١٠ سنين، وممكن زي ما بنقول في مرحلة المراهقة\nفاحنا نتخيل كده أب أو أم بيقولوا لابنهم الصغير روح هات كذا، فابنه راح قايله والله مانا رايح\nطبعا أنا مش هقولكم رد فعل الأب أو الأم إيه ساعتها، أنتم أكيد عارفين\nكان تصرف رسول الله ﷺ إيه بقى في الموقف ده\nمردش عليه ولا كلمه، سابه خاااالص من غير ما يعاتبه ولا يقوله حتى كلمة،\nبيكمل أنس الموقف وبيقول:\n\"فَخَرَجْتُ حتَّى أَمُرَّ علَى صِبْيَانٍ وَهُمْ يَلْعَبُونَ في السُّوق..\"\nيعني خرج أنس من عند رسول الله ﷺ عشان يروح يقضي لرسول الله ﷺ الحاجة إللي أمره بها وهو متظاهر أمام رسول الله ﷺ إنه مش هيروح يعمل لرسول الله ﷺ إللي هو عايزه،\nفا وهو ماشي عدّى على صبيان بيلعبوا، فوقف عندهم إما عشان يتفرج عليهم أو يشاركهم في اللعب،\nالمهم في اللحظة أنس بيقول:\n\"فَإِذَا رَسولُ اللهِ ﷺ قدْ قَبَضَ بقَفَايَ مِن وَرَائِي ...\"\nيعني رسول الله ﷺ خرج وراء أنس عشان يتابع هو هينفذ أمره ولّا لأ؛ لأن مينفعش الطفل يعند ونسيبه كده، هيزيد فيها، لكن المتابعة مهمة،\nفرسول الله ﷺ خرج وراء أنس، فلما شافه واقف عند الصبيان مسكه من قفاه، فأنس بص مين ده إللي مسكه فلقاه رسول الله ﷺ وواقف يضحك وقال له:\n\"يا أُنَيْسُ أَذَهَبْتَ حَيْثُ أَمَرْتُكَ؟\"\nيعني رسول الله ﷺ لما مسكه من قفاه مكنش ماسكه إمساك خنق، لكن كان إمساك ملاطفة، \nوبعدين قاله انت روحت زي ما قلت لك، فهنا أنس رضي الله عنه قال:\n\" نَعَمْ، أَنَا أَذْهَبُ، يا رَسولَ اللَّهِ\"\nيعني أنا رايح دلوقتي يارسول الله\n☆وهنا رسول الله ﷺ بيعلمنا إزاي نتعامل مع الطفل العنيد\nيعني لما نطلب من الطفل حاجة ويعند معانا نسيبه ومنردش عليه، لكن نتابعه، يعني نروح وراه ونتلطف معاه وبعدها نطلب منه الحاجة دي مرة تانية من غير لوم أو عتاب أو توبيخ على عناده ورفضه،\nورسول الله ﷺ عمل كده، مقلش لأنس ليه قلت والله لا أذهب، وإزاي أصلا تقولي كده وأنا رسول الله،\nمتكلمش خالص عن أي حاجة؛ لأن الغاية هي تنفيذ الأمر، وحصول المصلحة، مش إننا عايزين نعاتب ونتخانق ونمسك لهم على الواحدة\n♡موقف كمان لرسول الله ﷺ مع الأطفال، في مرة كان رسول الله ﷺ قاعد مع الصحابة، وكان على يساره شيوخ الصحابة رضي الله عنهم، وعلى يمينه غلام، والغلام هو الطفل قبل سن البلوغ، وقيل إن الغلام ده كان عبد الله بن عباس رضي الله عنه،\nفا وهم قاعدين جِيء لرسول الله ﷺ بشراب، منعرفش هو إيه بالضبط، هل لبن أو عسل، المهم إن حد جاب لرسول الله ﷺ حاجة يشربها،\nفشرب رسول الله ﷺ، وكان من عادته إنه يشارك أصحابه في الأكل والشرب إللي بيأتيه، والمفروض إنه يبدأ باللي على اليمين،\nلكن إللي على اليمين الغلام الصغير، وإللي على اليسار شيوخ الصحابة، فيعمل إيه ﷺ \nقَالَ لِلْغُلَامِ: أتَأْذَنُ لي أنْ أُعْطِيَ هَؤُلَاءِ؟ \nيعني رسول الله ﷺ بيستأذن الغلام الصغير إنه يعطي شيوخ الصحابة إللي على يساره الأول إكراما لهم، لكن الغلام قال لرسول الله ﷺ:\nواللَّهِ يا رَسولَ اللَّهِ، لا أُوثِرُ بنَصِيبِي مِنْكَ أحَدًا\nيعني هو رفض إنه يؤثر باقي الصحابة على نفسه ويعطيهم الشراب هم الأول،\nوالسبب في إنه لم يؤثرهم على نفسه هو إنه كان عايز ياخد أثر بركة رسول الله ﷺ بعد ما شرب،\nفهو مش مشكلته في الشرب نفسه، لكن هو كان عايز ياخد أثر بركة الشرب بعد رسول الله ﷺ، عشان كده قال:\nبنصيبي منك، يعني: مِن أثَرِ بركتِك\nفالشاهد من الموقف ده إن رسول الله ﷺ استأذن الطفل الصغير قبل ما يعطي كبار الصحابة، \nوهو كده بيعلمنا الاهتمام بالطفل، والتأكيد على إعطائه حقه، وإشعاره بقيمته، وتعويده الشجاعة وإبداء رأيه في أدب، وتأهيله لمعرفة حقه والمطالبة به\nوللأسف لأننا بِعدنا عن منهج رسول الله ﷺ في تربية الأبناء بقى حال الأطفال محزن، سواء من الناحية النفسية أو الأخلاقية إلا من رَحِم الله \n♡آخر موقف معانا النهاردة وهو من أعجب المواقف، بالنسبة لي على الأقل\n عبد الله بن الزبير بن العوام، ابن أسماء بنت أبي بكر أول مولود يُولد للمسلمين في المدينة بعد الهجرة،\nجاء لرسول الله ﷺ في يوم وهو بيعمل حِجامة، فلما رسول الله ﷺ خلّص قال لعبد الله بن الزبير:\n\"يا عبدَ اللهِ اذهَبْ بهذا الدمِ فأهرِقْه حيث لا يراكَ أحدٌ\"\nيعني روح كُب الدم ده في مكان من غير ما حد يشوفه،\nوهنا عبد الله بن الزبير كان صغير في السن، يعني أقل من عشر سنين؛ لأنه اتولد في السنة الأولى من الهجرة ورسول الله ﷺ مات في المدينة في أوائل السنة الحادية عشرة من الهجرة،\nومع صغر سن عبد الله بن الزبير رسول الله ﷺ بيعطيه مسؤولية كبيرة مع إنه كان ممكن يسأل حد من كبار الصحابة يتولى مسؤولية إخفاء دمه ﷺ،\nلكنه طلب ده من طفل عشان يعلمه تحمل المسؤولية وإنه يفكر وياخد قرار على الأساس ده\nأخد عبد الله بن الزبير الدم ومشي، فلما كان بعيد عن رسول الله ﷺ ومحدش شايفه راح واخد دم رسول الله ﷺ وقام شاربه\nفلما رجع لرسول الله ﷺ سأله رسول الله ﷺ:\nيا عبدَ اللهِ ما صنَعتَ ؟\nفقال عبد الله بن الزبير:\n\"جعلتُه في أخفى مكانٍ علمتُ أنه يَخفى عنِ الناسِ\"\nيعني أنا أخفيته في مكان محدش يقدر يوصل له\nفرسول الله ﷺ قال له:\n\"لعلَّكَ شرِبتَه\"\nفقال: نعَم.\nفقال له رسول الله ﷺ:\n\"لِمَ شرِبتَ الدمَ ؟ ويلٌ للناسِ مِنكَ وويلٌ لكَ منَ الناسِ\"\nيعني إيه إللي خلاك تشربه، بسبب إن بقى داخلك جزء مني فهتبتلى زي ما أنا ابتليت؛ لأن رسول الله ﷺ هو أشد الناس بلاءً ﷺ، وده معنى ويلٌ لكَ منَ الناسِ،\nأما معنى ويلٌ للناسِ مِنكَ هو إنك هيبقى عندك من العظمة والهمة والشجاعة والإقدام ما الله به عليم،\nوفعلا لما كبر عبد الله بن الزبير اشتهر بالتقوى والصلاح والزهد والورع، والفصاحة والبيان والعلم والفضل،\nوالشجاعة وشارك في الفتوحات الإسلامية، وهو أحد العَبَادِلَة الأربعة\n☆مين العبادلة الأربعة دول\nده إللي هنعرفه المرة الجاية إن شاء الله \nبس قبل قبل ما ننهي جزء النهاردة عندنا سؤال:\n☆إزاي عبد الله بن الزبير يشرب دم رسول الله ﷺ ومعروف إن الدم نجس لا يجوز شربه\nالعلماء قالوا إن دي حاجة خاصة برسول الله ﷺ انفرد بها في الحكم عن باقي الأمة، فبعض أهل العلم نص على طهارة دمه الشريف ﷺ\nمصادر جزء النهاردة في التعليقات"}, {"n": 241, "l": "الجزء 215 | بعض مواقف رسول الله مع الشباب", "u": "https://www.facebook.com/groups/710210019782034/permalink/837712653698436/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وخمسة_عشر\n#أحداث_السنة_التاسعة_من_الهجرة\n#بعض_مواقف_رسول_الله_مع_الشباب\nوقفنا المرة إللي فاتت عند سؤال: من هم العَبَادلة الأربعة؟\nلقب العبادلة الأربعة أُطلق على أربعة من الصحابة، هم:\n◇عبد الله بن عمر بن الخطاب رضي الله عنه \n◇وعبد الله بن عباس بن عبد المطلب رضي الله عنه \n◇وعبد الله بن الزبير بن العوام رضي الله عنه \n◇وعبد الله بن عمرو بن العاص رضي الله عنه \nوالسبب في إن العلماء وأهل الحديث سموهم كده لأنهم كانوا من صغار الصحابة ومع ذلك جمعوا علمًا واسعًا، ولأنهم عاشوا زمن طويل بعد موت رسول الله ﷺ، فالناس اتعلموا منهم كتير،\nفإذا اتفقوا هم الأربعة على شيء قيل: \nهذا قول العبادلة، أو فعلهم، أو مذهبهم.\n☆طيب وعبد الله بن مسعود ميدخلش معاهم ليه\nلأن عبد الله بن مسعود تقدمت وفاته، يعني مات قبلهم بكتير، لكن الأربعة عاشوا فترة طويلة حتى احتِيج إلى علمهم\nهنتكلم النهاردة بقى إن شاء الله عن موقفين لرسول الله ﷺ مع شابين من شباب الصحابة،\nرسول الله ﷺ بصفة عامة كان عارف طبيعة مرحلة الشباب إللي فيها أقصى درجات القوة والحيوية والنشاط وتُعتبر من أهم المراحل إللي بيمر بها الإنسان؛ لأن شخصيته تبدأ بالتكون والتطور من كل النواحي، فيكتسب المهارات، والمعارف وغيرها من الأمور، \nعشان كده كان رسول الله ﷺ بيوجههم ويرشدهم بما يتناسب مع قدراتهم وشخصايتهم ويشجعهم ويعطيهم من المهام إللي ترفع همتهم وتقوّي نفوسهم،\nوكان ﷺ يرفق بالشباب ويرشدهم باللي ينفعهم،\nوفي الوقت نفسه يستخرج مواهبهم ويستفيد من طاقاتهم\n♡أول موقف معانا النهاردة هو موقف رسول الله ﷺ مع معاذ بن جبل رضي الله عنه، \nفي مرة كده رسول الله ﷺ أخذ بيد معاذ وقال له:\n\"يَا مُعَاذُ ! وَاللَّهِ إِنِّي لَأُحِبُّكَ\"\nهنا رسول الله ﷺ بيحلف لمعاذ إنه بيحبه، ولكم أن تتخيلوا إحساس معاذ لما رسول الله ﷺ يقوله كلمة زي دي فجأة\nفقال معاذٌ: بأبي أنتَ وأُمِّي واللهِ إنِّي لأُحِبُّك.\nفقال له رسول الله ﷺ:\n\"يا معاذُ! أوصيك ألَّا تدَعَنَّ في دبُرِ كلِّ صلاةٍ أنْ تقولَ: اللَّهمَّ أعِنِّي على ذِكرِك وشُكرِك وحُسنِ عبادتِك\"\nيعني رسول الله ﷺ بيوصي معاذ إنه قبل ما يسلّم من الصلاة؛ يدعو الله ويطلب منه الإعانة على ذكره عز وجل وشكره وحسن عبادته،\nفهنا رسول الله ﷺ عشان يعلّم معاذ رضي الله عنه ذِكر مهم لفت انتباهه الأول له بإنه أخبره إنه يحبه،\nوده فضل عظيم لمعاذ رضي الله عنه،\nفرسول الله ﷺ لما قال لمعاذ إني أحبك الطبيعي إنه يقع في قلب معاذ إن إللي بيحب حد هيدلّه على الخير، وهو ده إللي رسول الله ﷺ عمله، وبكده معاذ رضي الله عنه مستحيل ينسى الذكر ده لأنه ارتبط بتعبير رسول الله ﷺ عن محبته له\nومعاذ بن جبل رضي الله عنه أسلم وعمره ثمانية عشرة عام، وحضر بيعة العقبة الثانية، وحضر الغزوات كلها مع رسول الله ﷺ، وقال عنه رسول الله ﷺ بأنه أعلم الأمة بالحلال والحرام، وبعد فتح مكة تركه رسول الله ﷺ هناك عشان يعلم الناس الدين، مع إن عمره ساعتها كان ستة وعشرين سنة فقط،\nومش بس كده ده رسول الله ﷺ بعثه وبعثه إلى اليمن معلما وداعيا وأميرا،\nففي السنة التاسعة من الهجرة بعد غزوة تبوك واستقرار الأوضاع وظهور الإسلام؛ أمر رسول الله ﷺ معاذ إنه يسافر لليمن عشان يدعوا أهلها للإسلام، فقال له رسول الله ﷺ:\n\"إِنَّكَ ستأتي قَوْمًا أهلَ كتابٍ،\n فإذا جئتَهم فادْعُهم إلى أنْ يشهدُوا أنْ لَا إِلَهَ إلَّا اللهُ ، وأنَّ محمَّدًا رسولَ اللهِ، \nفإِنْ هم أطاعوا لَكَ بذلِكَ، فأخبرْهم أنَّ اللهَ قَدِ فرَضَ عليْهِمْ خمسَ صلَوَاتٍ في كُلِّ يومٍ وليلَةٍ، فإِنْ هم أطاعوا لَكَ بذلِكَ، فأخبرْهم أنَّ اللهَ قدْ فَرَضَ عليهم صَدَقَةً تُؤْخَذُ منْ أغنيائِهم ، فتردُّ على فقرائِهم،\n فإِنْ هم أطاعوا لَكَ بِذَلِكَ ، فإيَّاكَ وكرائِمَ أموالِهم، واتَّقِ دعوَةَ المظلومِ ، فإِنَّه ليسَ بينها وَبينَ اللهِ حجابٌ\"\nيعني رسول الله ﷺ بيشرح لمعاذ طبيعة الناس إللي هيروح يدعوهم، فهم أهل كتاب،\nوبيعلمه إنه يتدرج معاهم في الدعوة عشان ميبقاش الدخول في الإسلام ثقيل عليهم،\nفأول حاجة يدعوهم إليها هي عبادة الله وحده والإيمان بأن محمد ﷺ رسول من عند الله،\nفلو همّ استجابوا، ساعتها بقى يبدأ يقولهم أحكام الإسلام،\nويقول لهم إن ربنا فرض عليهم خمس صلوات في اليوم والليلة، فلو استجابوا؛ يقولهم إن  ربنا فرض عليهم الزكاة، وهي مال يؤخذ من أغنيائهم ويُنفق على فقرائهم،\nوقاله إنه مياخدش من نفائس الأموال في الزكاة، يعني ياخد الوسط، لا العالي ولا النازل،\nيعني مثلا لو ناس عندهم أغنام وعليها زكاة، ميروحش ياخد أحسن واحدة عندهم وإللي بتكون نفسوهم متعلقة بيها،\nوبيحذّره إنه لو عمل كده هيبقى الموضوع فيه ظلم، وكده هيعرض نفسه لدعوة المظلوم إللي مفيش بينها وبين ربنا حجاب\n☆ممكن حد يسأل ويقول: طيب ليه رسول الله ﷺ مقلش على بقية أركان الإسلام في الحديث\n◇أولا: لأن إللي بيصلي الصلوات الخمس فقد أدى أعظم العبادات البدنية،\nوإللي بيؤدي الزكاة فهو بيؤدي أعظم الحقوق المالية،\nفاللي بيؤدي أعظم عبادتين هيقدر يؤدي العبادات التانية إللي أقل منها في الجَهد،\nيعني مثلا لما رسول الله ﷺ يقول:\n\" مَنْ صَلَّى الْبَرْدَيْنِ دَخَلَ الْجَنَّةَ\"\nوالبَرْدَان هما : الفجر والعّصْر ، يعني إللي يصلين الفرضين دول مع ثقلهما بعد تعب ونوم فهو أكيد باقي الصلوات هيبقى سهل عليه يصليهم\n◇ثانيا:\nأن الإنسان إنما يُخاطَب بالصيام وبالحج إذا حضر وقته ولَزِم وُجوبه، يعني لما ييجي وقت الصيام والحج ساعتها يبقى يقولهم عليهم، وكمان من باب التدرج معاهم في الفرائض\nفالشاهد من القصة دي كلها إن رسول الله ﷺ وجّه طاقة معاذ بن جبل رضي الله عنه في المفيد، واختاره هو بالذات للمهمة دي بسبب علمه وقدراته على صغر سنه\nآخر حاجة مع معاذ بقى، لما كان خلاص ماشي ومتجه لليمن وكان راكب على راحلته ورسول الله ﷺ ماشي على قدمه تحت الراحلة جنب معاذ وبيوصيه؛ قال له بعد ما انتهى من وصيته:\n\"يَا مُعَاذُ! إِنَّكَ عَسَى أَنْ لَا تَلْقَانِي بَعْدَ عَامِي، وَلَعَلَّكَ أَنَّ تَمُرَّ بِمَسْجِدِي وَقَبْرِي\" \nيعني رسول الله ﷺ بيقول لمعاذ إن ده ممكن يكون آخر لقاء بينه وبينه ﷺ، وإنه لما يرجع للمدينة من الرحلة دي ويمر بالمسجد مش هيلاقي رسول الله ﷺ لأنه ساعتها هيكون مات\nالموضوع كان محزن جدا لمعاذ رضي الله عنه لدرجة إنه بكى جَزَعًا لِفِرَاقِ رسول الله ﷺ\nيعني لم يصبر وبكى بصوت عالي فيه صراخ، فقال له رسول الله ﷺ:\n\"لَا تَبْكِ يَا مُعَاذُ، فَإِنَّ الْبُكَاءَ مِنَ الشَّيْطَانِ\"\nيعني رسول الله ﷺ بينهى معاذ عن البكاء إللي يصاحبه جزع وعدم صبر وفيه نياحة وعلو صوت، مش بينهاه عن البكاء العادي إللي تدمع فيه العين عشان محدش يفهم خطأ\nوالموقف ده كان آخر لقاء بين رسول الله ﷺ وبين معاذ بن جبل قبل موته ﷺ،\nفمعاذ لم يلتقِ برسول الله ﷺ مرة تانية بعد وداعه في الموقف ده، فهو رجع للمدينة بعد وفاة رسول الله ﷺ، \nوبعدها بكم سنة خرج للشام وشارك في فتوحات الشام ومات رضي الله عنه في طاعون عَمْواس سنة سبعة عشر هجريا وكان عمره خمسة وثلاثين سنة رضي الله عنه وجمعنا به في الفردوس الأعلى مع رسول الله ﷺ\n☆ملحوظة:\nبحاول وأنا بحكيلكم عن سيرة رسول الله ﷺ إني أقولكم نبذة مختصرة عن الصحابة بحيث تطلعوا من السلسة دي عارفين قصة حياة رسول الله ﷺ وقصص الصحابة بصفة عامة ويبقى عندكم صورة متكاملة عنهم، فمعلش يعني لو لقيتوني طلعت برة الموضوع الأصلي \n♡موقفنا التاني النهاردة، موقف من أعجب المواقف إللي حصلت فعلا في عهد رسول الله ﷺ\nجاء فتى شاب لرسول الله ﷺ وهو قاعد مع الصحابة وطلب منه إنه يأذن له في الزنا\nالشاب لسه صغير مش مستوعب أوي الموضوع، يعني هو عارف إن الزنا حرام، لكن هو عايز زي ما بنقول كده استثناء من رسول الله ﷺ إنه يسمح له بالزنا، ويبقى له هو حلال مش حرام،\nفالصحابة إللي كانوا حاضرين وسمعوا كلام الشاب صاحوا به وزَجروهُ وقالوا: مَهْ. مَهْ.\nيعني الصحابة زعقوا له وقالوا له اسكت إيه إللي انت بتقوله ده وحاولوا إنهم ينهوه عن الاستمرار في طلبه\n☆عارفين الموقف ده كده في واقعنا زي مثلا لما يبقى في حد بيسأل سؤال أو بيطلب طلب وهو في عُرف الناس سؤال تافه أو مينفعش يسأله أو طلب هم مستنكيرنه، إزاي تسأل أو تطلب ده،\nفيبدأوا بقى يعلقوا على السائل ويحاولوا يسكتوه وفي إللي للأسف ممكن يتعدى عليه بشيء من الكلام الجارح\nطيب رسول الله ﷺ النبي المُرسل من رب العالمين، الحاكم إللي مسؤول عن تطبيق أحكام الشرع وإللي طبق قبل كده حد الزنا على ماعز والغامدية عمل إيه واتصرف إزاي في الموقف ده\nرسول الله ﷺ قال بكل هدوء:《 قَرِّبوهُ》\nيعني خلوه يقرب مني، عشان يديله الأمان في وسط الهجوم الشديد إللي حس بيه في البداية\n فقرب الشاب من رسول وجلس أمامه، هنا رسول الله ﷺ مكلموش بالحلال والحرام؛ لأن الشاب عارف إن الزنا حرام أصلا، وحكم الزنا مش حاجة رادعة للشاب ده، وإلا مكنش طلب الإذن في الزنا\nفلازم حاجة تانية تقنعه وبالتالي ييجي الرفض من داخله هو\nفهنا رسول الله ﷺ استعمل معاه أسلوب العقل مع العاطفة، قال له:\n《 أتحبُّهُ لأُمِّكَ ؟》\nيعني انت ترضى إن أحد يزني بأمك؟\nفالشاب قال له: لا واللَّهِ، جعلَني اللَّهُ فداءَكَ\nيعني طبعا لأ، مستحيل أرضى إن حد يزني بأمي، فهنا رسول الله ﷺ قال للشاب:\n《ولا النَّاسُ يحبُّونَهُ لأمَّهاتِهِم》\nيعني زي مانت متحبش إن حد يزني بأمك كذلك الناس محدش فيهم يحب أن يزني أحد بأمهاتهم\nورسول الله ﷺ بدأ بالأم لأن هي في منزلة الحُرْمة والمحبة عند ابنها أعلى في المنزلة من أي حد تاني، فطبيعي إنه يستنكر جدا أن يزني أحد بأمه،\nورسول الله ﷺ موقفش عند النقطة دي، ده كمل كلامه وقال:\n《 أفتحبُّهُ لابنتِكَ ؟ 》\nوالبنتُ هي مَحلُّ الشَّرفِ والكرامةِ لأبيها ولو وقعت في الفاحشة يلحق بأبيها العار بما لا يلحقه بغيرها،\nفالشاب قال له:\nلا واللَّهِ يا رسولَ اللَّهِ جَعلَني اللَّهُ فداءَكَ \nفقال له رسول الله ﷺ:\n《ولا النَّاسُ يحبُّونَهُ لبَناتِهِم》\nوبدأ رسول الله ﷺ يتدرج معاه، أتحبه لأختك...أتحبه لعمتك...أتحبه لخالتك...والشاب كل مرة يقول:\n\"لا واللَّهِ يا رسولَ اللَّهِ جَعلَني اللَّهُ فداءَكَ\"\nورسول الله ﷺ يقول له في كل مرة:\n\"ولا النَّاسُ يحبُّونَهُ لأخواتِهِم...ولا لعمَّاتِهِم....ولا لخالاتِهِم\"\nفالشاهد من حوار رسول الله ﷺ مع الشاب إنه كان عايز يوصل له معنى معين وهو إن الإنسان إذا كان لا يرضى إن حد يعمل الفاحشة مع أهله فطبيعي إنه لا يطلب هو فعل الفاحشة مع أحد؛\nلأن زي مانت خايف على عرضك فالناس كمان خايفين على أعراضهم، ولا يؤمن أحدكم حتى يحب لأخيه ما يخب لنفسه،\nوكمان تخاف إن حد يفعل الفاحشة في أهلك زي مانت تجاوزت حدود الله وفعلت الفاحشة مع بنات الناس\nبعد ما رسول الله ﷺ أنهى حواره مع الشاب وضع رسولُ اللهِ ﷺ على صدرِ الشاب وقال :\n《اللهمَّ طهِّرْ قلبَه واغفر ذنبَه وحصِّنْ فَرْجَه》\nيعني رسول الله ﷺ دعا له إن ربنا يمحو ذنوبه، ويطهر قلبه من حب الفواحش والمعاصي ويحوله لحب الطاعات والعبادات، ويحفظه من الوقوع في الحرام،\nفلم يكن شيءٌ أبغضَ إليه منه\nيعني الشاب بقى أكتر حاجة بيكرهها هي الزنا ببركة دعاء رسول الله ﷺ له.\n☆من خلال موقف رسول الله ﷺ ده نتعلم نقطتين مهمين جدا:\n♡أول حاجة:\nإننا يبقى عندنا سعة صدر لما حد يحكي لنا على خطأ وقع فيه، أو شيء خطأ عايز يعمله من غير ما نزعق ولا نتخانق، زي ما رسول الله ﷺ عمل كده، وخصوصا الآباء والأمهات،\nنسأل نفسنا كده ليه لما حد من عيالنا يقع في الخطأ أو نفسه تحدثه بفعل الخطأ مش بيلجأ لأمه وأبوه ويقولهم؟\nلأن الأبناء عارفين رد الفعل من خناق وزعيق وعقاب بدون حل صحيح لأصل المشكلة وكأن الأبناء دول المفروض يكونوا ملايكة مش بيغلطوا\n♡تاني حاجة:\nهي الرفق واللين في التعامل مع الشخص إللي عايز يعمل معصية واختيار الأسلوب الأمثل في الإقناع، وإننا نتفهم موقفه ومشاعره،\nفرسول الله ﷺ بيرشدنا للطلف بالجاهل قبل ما نعلمه، وده أنفع له من التعنيف، \nوخصوصا وهو عارف إن إللي هيعمله او عمله ده حرام أو خطأ،\nيعني رسول الله ﷺ مكلمش الشاب في حلال وحرام، لكنه خاطب عنده العقل والعاطفة بأسلوب تفاعلي في الحوار، \nيعني رسول الله ﷺ مقلوش انت أكيد متحبش إن حد من أهلك يقع في الزنا،\nلكن خلى في تفاعل في الحوار، هو يسأل والشاب يجاوب عشان الشاب هو إللي يطلع في الآخر بالنتيجة ويبقى هو إللي جاوب على نفسه بنفسه،\nوخصوصا إن الشباب بيبقوا عايزين يثبتوا نفسهم وآراءهم،\nفاللي توصل للإجابة وحل المشكلة كان الشاب نفسه بتوجيه من رسول الله ﷺ أعظم مربي ﷺ \n وفي الآخر رسول الله ﷺ دعا له،\nفالداعية مع العاصي أو الأم والأب مع الأبناء لما يتبعوا منهج رسول الله ﷺ ده هيبقى أدعى إنهم يقربوهم من ربنا ويبعدوهم عن الوقوع في الخطأ ويحسسوهم بحرصهم عليهم ورغبتهم الصادقة في هدايتهم وإصلاحهم فتكون النتيجة زي ما حصل مع الشاب، إنه كره الفاحشة أصلا\nطبعا الحديث مليان فوائد كتير جدا بس أنا قلت أهم نقطتين عشان نقدر نحولهم لواقع عملي\n◇عندنا بقى سؤال مهم عن قضية الزنا\nهل لو واحد زنى ممكن يترد له في أهله؟\nيعني يترد له في أخته أو بنته أو زوجته مثلا\nبراحة كده وواحدة واحدة وركزوا معايا\nربنا وضع لنا قاعدة عامة في القرآن بتقول:\n\" وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ\"\nيعني بالبلدي كده محدش بيتحاسب بذنب حد، كل واحد بيتحاسب بأفعاله هو بس، تمام كده\nلكن من سنن ربنا الغالبة أن الصلاح متوارث وكذلك الفساد متوارث،\nيعني غالبا إللي أهله كلهم فاسدين بيطلع هو كمان فاسد، وإللي أهله كلهم صالحين غالبا بيطلع هو كمان صالح،\nعشان كده بتبقى حاجة غريبة أن يوجد الفساد في بيوت الصلاح، وأن يوجد الصالح في بيوت الفساد،\nولو تفتكروا بني اسرائيل لما شافوا مريم جاية لهم بطفل من غير أب استغربوا إزاي هي من بيت صلاح ويقع منها شيء زي كده وقالوا لها:\n\"يَا أُخْتَ هَارُونَ مَا كَانَ أَبُوكِ امْرَأَ سَوْءٍ وَمَا كَانَتْ أُمُّكِ بَغِيّاً\"\nفإذا كان الأب فاسد فأكيد تربيته هتبقى فاسدة، فإذا وقع في الزنا ووقعت ابنته في الزنا مثلا فده مش لأن ده ذنب أبوها وهي بتدفع الثمن، لأ،\nهي وقعت في الزنا بسبب فسادها هي وعدم تقواها، فهي تشيل ذنب فسادها هي مش ذنب زنا أبوها،\nوكذلك الحال برده لو حد زنا مع زوجة الرجل الفاسد الزاني ده،\nفلأن الرجل توجه للزنى فلن يَعُف زوجته، وإذا لم يعُفّها تشوّقت هي إلى غيره فزنت به كما هو الغالب على نساء الزواني،\nوده كلام شيخ الإسلام ابن تيمية رحمه الله،\nفوقوع الزوجة في الزنا مش عقاب من الله لها على زنا زوجها وإن الزنا يترد له في أهله، لأ، ده بسبب ما كسبت أيديهم من الفساد وعدم تقواهم لله\nده غير إن الرجل إذا وقع في الزنا وكان معروف بكده وسط أهله سواء كان زوج أو أخ أو أب فده بيشجع أهله إنهم يعملوا زيه،\nولو وقعوا في الزنا وغيرها من الفواحش بيبقى بسبب قلة غيرته وانغماسه هو نفسه في الفواحش وهوان المعصية في نفوسهم، ولو نصحهم ناصح يقولوا عادي ما أبونا بيعمل كده\nوفي بنات بيبقوا مصاحبين شباب ولما حد ينصحهم ويقولهم كده حرام يقولوا ما هو ماما وبابا عارفين\nوفي منهم إللي بيقع في الزنا والعياذ بالله بسبب التهاون ده، وفي نفس الوقت ممكن يكون الأب وقع في الزنا في شبابه برده، \nلكن هل معنى كده إن بنته مثلا وقعت في الزنا بذنب أبوها؟\nلأ، هي وقعت فيه بسبب تهاونها هي وتعديها على حرمات الله\nطيب ممكن يكون الرجل فاسد ووقع في الزنا أو غيرها من الفواحش وزوجته أو بنته أو أخته نساء صالحات وممكن حد يعتدي عليهن مثلا سواء بزنا أو بلمسة أو بقبلة أو...أو...؟\nأه ممكن، لكن الاعتداء ده ساعتها يكون بسبب ذنوبها هي بصفة عامة، فالموضوع يضايقها فربنا يكفر عن سيئاتها بسبب الهم والغم إللي هتكون فيه،\nورسول الله ﷺ قال:\n\"مَا يُصِيبُ الْمُسْلِمَ مِنْ نَصَبٍ وَلاَ وَصَبٍ وَلاَ هَمٍّ وَلاَ حَزَن وَلاَ أَذًى وَلاَ غمٍّ، حتَّى الشَّوْكَةُ يُشَاكُها إِلاَّ كفَّر اللَّه بهَا مِنْ خطَايَاه\"\nوفي نفس الوقت بقى الاعتداء ده يكون عقوبة وقهرة للرجل الفاسد الزاني\nيعني يا جماعة الموقف الواحد ممكن يكون له حِكم وأسباب لا يعلمها إلا الله، زي كده قصة الرجل إللي وصى ابنه لما كان ناوي على السفر وقال له:\nاحفظ أختك في سفرك، فالابن استغرب من وصية أبوه، إزاي هيحفظ أخته وهو مش هيبقى موجود\nففي يوم الأب شاف السقّا إللي بيوزع المية على البيوت بيقبّل ابنته،\nفلما رجع الولد أبوه قاله مش قلت لك احفظ أختك في سفرك، \nوكان الشاب وهو في سفره شاف بنت فعجبته فأغواه الشيطان فقبلها غصب عنها، \nفلما أبوه قاله كده عرف إن في حاجة حصلت في البيت، فحكى له أبوه إللي حصل وحكى الشاب لأبوه إللي عمله، \nفقال له أبوه:\n\"يا بُنيّ دقة بدقة ، ولو زدت لزاد السقا\"\nفهنا البنت صالحة عفيفة، إيه ذنبها بقى إن يحصل معاها كده مع إن أخوها هو إللي أخطأ؟\nنقول هنا إن إللي وقع للبنت ده ابتلاء بما كسبت أيديها من معاصي بصفة عامة في حياتها فيكون الابتلاء ده تكفير لسيئاتها أو رفع درجاتها\nأما بالنسبة للأخ فهو عقوبة وحرقة دم له وقهرة على فعله إللي فعله ده وطبعا دافع له إنه يتوب ويستغفر وإنه ميعملش كده تاني\nوطبعا حكم ربنا مش هنقدر نستوعبها بعقلنا المحدود ده، لكن يكون عندنا ثقة إن ربنا لا يظلم مثقال ذرة ولا يعاقب أحد بذنب أحد أبدا\nمعلش طولت عليكم النهاردة \nإن شاء الله المرة الجاية هنتكلم عن بعض مواقف رسول الله ﷺ مع الحيوانات،\n \n مصادر جزء النهاردة في التعليقات"}, {"n": 242, "l": "الجزء 216 | بعض المواقف لرسول الله مع الحيوانات", "u": "https://www.facebook.com/groups/710210019782034/permalink/837713143698387/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وستة_عشر\n#أحداث_السنة_التاسعة_من_الهجرة\n#بعض_المواقف_لرسول_الله_مع_الحيوانات\nاتكلمنا قبل كده عن مواقف لرسول الله ﷺ مع الصحابة بصفة عامة وتعامله معاهم،\nواتكلمنا عن تعامل رسول الله ﷺ مع زوجاته وشوفنا إزاي كان بيعالج أخطاءهم،\nواتكلمنا عن تعامله مع الأطفال ومع الشباب، \nالنهاردة الموضوع مختلف\nلأن المواقف المرة دي مش مع البشر، المواقف المرة دي مع الحيوانات\nربنا بيقول عن رسول الله ﷺ:\n\"وَمَا أَرْسَلْنَاكَ إِلَّا رَحْمَةً لِلْعَالَمِينَ\"\nوكلمة العالَمِين دي يدخل فيها الحيوانات كمان مش بس الإنس والجن\nواحنا عارفين إن الناس في الجاهلية كانوا بياعملوا العبيد معاملة سيئة، فما بالكم بالحيوانات\nفجاء الإسلام بأحكامٍ توضح وتبيّن حدود التعامل مع الحيوان، وتحذر من الاعتداء عليه بغير حق\n زي المرأة إللي حبست قطة فلا هي أطعمتها ولا هي تركتها تأكل من رزق الله، لحد ما ماتت من الجوع فكان عقابها إن ربنا أدخلها النار\nفي حين إن رجل شاف كلب بياكل التراب إللي فيه رطوبة من شدة العطش فنزل للبئر وأخرج منه الماء وسقى الكلب فكان جزاؤه الجنة،\nورسول الله ﷺ لما حكى للصحابة قصة الرجل ده سألوه:\nوإنَّ لنا في البهائم أجر؟!\nيعني احنا هناخد أجر لو سقينا الحيوانات، فقال لهم رسول الله ﷺ:\n\"في كلِّ كَبِدٍ رَطْبةٍ أجرٌ\"\nيعني كل كائن حي إذا أطعمته وسقيته هتاخد عليه أجر\n♡من المواقف إللي حصلت مع رسول الله ﷺ وأمر فيها بالرفق بالحيوان إنه مرة كان ماشي في المدينة فعدّى على بعير...جمل... قد لحِقَ ظَهْرُهُ ببطنِهِ، يعني من شدة الجوع والتعب الجمل بقى بطنه داخلة لجوة كده لحد ما بقى هزيل وضعيف،\nفرسول الله ﷺ قال:\n\"اتَّقوا اللَّهَ في هذهِ البَهائمِ المعجَمةِ فاركَبوها صالِحةً وَكُلوها صالحةً\"\nيعني خافوا ربنا في البهائم إللي مبتقدرش تشتكي من ألمها وتتكلم دي، وربنا هيسألكم عن جوعها وعطشها وأتعبتوها في إيه، \nفالبهائم القوية إللي تستحمل الشغل والمشقة استعملوها واركبوها، مش تستعملوا الضعيفة الهزيلة،\nوكلوها لما تكون سليمة معافاة تَتشبَّعُ باللَّحمِ والسِّمَنِ، مش تسيبوها لحد ما يُهْلِكها الضعف من الجوع أو المرض\nفالإسلام يأمر بعدم إجهاد البهائم فوق طاقتها ومراعتها في المأكل والمشرب.\n♡موقف تاني بيحكيه عبد الله بن جعفر بن أبي طالب، وعبد الله بن جعفر أمه أسماء بنت عُميس الحبشية البحرية زي ما سماها عمر بن الخطاب رضي الله عنه واتكلمنا عنها في الجزء المائة وتسعة وثلاثون\n \nفأسماء بنت عميس ولدت ابنها عبد الله بن جعفر في الحبشة في السنة الأولى من هجرة رسول الله ﷺ للمدينة،\nفكده أبوه مات وهو عنده حوالي سبع أو ثماني سنوات، لأن جعفر رضي الله عنه قُتل شهيدا في معكرة مؤتة في السنة الثامنة من الهجرة،\nالمهم بقى عبد الله بن جعفر رضي الله عنه بيحكي وبيقول إن رسول الله ﷺ ركّبه وراه وهو صغير كده على دابة ومشيوا مع بعض يتكلموا، \nفأخبره رسول الله ﷺ بسر، وعبد الله بن جعفر مقلش لحد على السر ده.\n☆وهنا رسول الله ﷺ بيعلم عبد الله بن جعفر الطفل الصغير وبيربيه على الأمانة وتحمّل مسؤولية حفظ السر \nوهم ماشيين رسول الله ﷺ نزل عشان يقضي حاجته، وكان رسول الله ﷺ بيحب يستتر وراء مكان مرتفع لقضاء الحاجة زي البناء أو غيره،\nأو يستتر خلف حائِشَ نَخْلٍ، وهو النَّخْلُ المُلْتَفُّ المُجْتَمِع بعضُه على بعضٍ، يعني بيبقى عاملة زي غابة كده مليانة شجر\nفدخل رسول الله ﷺ بستان لواحد من الأنصار، فلقى جمل في البستان، أول ما الجمل شاف رسول الله ﷺ حنَّ وذرِفَت عيناهُ\nيعني عمل صوت ونزلت الدموع من عين الجمل، فرسول الله ﷺ راح ناحيته ومسح ذِفراهُ، يعني مسح  المكان إللي البعير بيَعْرَق منه عند أُذُنِه، فسكت الجمل ومبقاش يعمل صوت ولا بقت دموعه تنزل،\nفقال رسول الله ﷺ:\nمَن ربُّ هذا الجَمَلِ، لمن هذا الجمَلُ؟\nيعني مين صاحب الجمل ده والمسؤول عنه؟!\nفَجاءَ فتًى منَ الأنصارِ فَقالَ:\n لي يا رسولَ اللَّهِ\nفَقالَ له رسول الله ﷺ:\nأفلا تتَّقي اللَّهَ في هذِهِ البَهيمةِ الَّتي ملَّكَكَ اللَّهُ إيَّاها؟\nفإنَّهُ شَكا إليَّ أنَّكَ تُجيعُهُ وتُدئبُهُ.\nيعني مش تتقي ربنا في البهيمة إللي خلاك تملكها دي؟! \nوهو هنا بينبهه إن ربنا هو إللي ذلل له الجمل عشان يساعده، يعني دي نعمة من ربنا، فإزاي بقى ميراعيش النعمة دي،\nورسول الله ﷺ وضّح له المشكلة في إيه وقال له إن الجمل اشتكى له إنه بيجوّعه ومش بيأكّله لحد ما الجوع بيؤذيه،\nوكمان بيتعبه ويجهده بالأعمال الكثيرة،\nوطبعا دي معجزة واضحة لرسول الله ﷺ إنه عرف إللي بيشتكي منه الحيوان\n☆طيب رسول الله ﷺ إزاي فهم الجمل\nحاجة من اتنين:\nإما إن ربنا جعل رسول الله ﷺ يفهم شِكاية الجمل، زي ما ربنا علّم سليمان عليه السلام لغة الطير وباقي الحيوانات،\nأو إن رسول الله ﷺ عرف مشكلة الجمل عن طريق الوحي،\nوأيًّا كان يعني فدي آية ومعجزة لرسول الله ﷺ شافها الصحابة ونقلوها لنا\n♡موقف ثالث لرسول الله ﷺ بيحكيه عبد الله بن مسعود بيقول إنهم كانوا مرة في سفر مع رسول الله ﷺ، فتركهم رسول الله ﷺ وراح لمكان بعيد عشان يقضي حاجته،\nفي الوقت ده الصحابة شافوا\n《حُمَّرةً معها فَرخَان》\nيعني شافوا طائر شبه العصفورة معاها أولادها الاتنين، فالصحابة أخذوا الفَرخِين الصغيرين،\nفأمهم جاءت وقعدت تطير وتُرفْرِفُ فزعًا، فجاء رسول الله ﷺ وهم على الحالة دي، فقال:\nمن فجَع هذه بولدِها ؟ رُدُّوا ولدَها إليها.\nيعني مين إللي أحزن وخوّف الطائر ده بأخذ صغارها، وأمرهم إنهم يرجعوا لها صغارها،\nوكان الصحابة برده حرقوا قرية للنمل، فشاف رسول الله ﷺ قرية النمل محروقة، فسأل مين إللي حرق قرية النمل دي،\nفالصحابة قالوا له إنهم هم إللي حرقوها،\nفقال لهم:\n\"إنه لا ينبغي أن يعذِّبَ بالنارِ إلا ربُّ النارِ\"\nيعني مينفعش أي إنسان إنه يعذب بالنار أي روح سواء كانت روح إنسان أو روح حيوان؛ لأن إللي بيعذب بالنار هو خالقها فقط وهو الله عز وجل،\nوده نهْي صريح عن إن حد يحرق أي روح بالنار أو يعذبها بها\nطبعا يا جماعة الصحابة مكنوش يعرفوا إن إللي عملوه ده كان غلط لحد ما رسول الله ﷺ أخبرهم بده وإلا مكنش حد فيهم عمل كده\n☆ملحوظة مهمة بقى:\nفي ناس عشان تقتل حشرات زي النمل مثلا أو غيرها من الحشرات المؤذية تقوم تكب عليهم مية سخنة\nده لا يجوز يا جماعة\nلأن ده كده يدخل في القتل بالنار وكمان تعذيب يتنافى مع حُسْن القِتلة إللي رسول الله ﷺ أمر به في الحديث:\n\"إن الله كتب الإحسان على كل شيء، فإذا قتلتم فأحسنوا القتلة، وإذا ذبحتم فأحسنوا الذبح\"\nفإذا كنّا عايزين نقتل شيء فيجب علينا اختيار أسرع وسيلة لإزهاق الروح دي بدون تعذيب جسدي أو حتى تعذيب نفسي\nوبمناسبة التعذيب النفسي، رسول الله ﷺ عدّى على رجل واضع رجله على رقبة شاة مثبتها في الأرض عشان عايز يذبحها، وهوَ يُحدُّ شفرتَه وهيَ تلحَظُ إليه ببصَرِها، يعني الرجل واقف يسِن السكينة إللي هيذبحها بها والشاة شايفة الموقف كله،\nفقال له رسول الله ﷺ:\nأفلا قَبلَ هذا ؟ أو تريدُ أن تُمِيتَها مَوتاتٍ؟\nيعني مش كنت تسِن السكينة دي قبل ما تيجي تذبحها، ولّا انت عايز تموتها أكتر من مرة؛ مرة تموّتها بالخوف ومرة تموتها بالذبح نفسه،\nفهنا رسول الله ﷺ بيعلمنا الرفق بالحيوان وعدم تعذيبه أو إخافته حتى عند موته\nومش بس كده، ده رسول الله ﷺ نَهى عن التحريش بين الحيوانات يعني تهييج بعضها على بعض، زي مصارعة الديُوك والجمال وغيرها،\nوسبب النهي إن ده في إيلام للحيوانات وإتعابٌ لها بدون فائدة، والموضوع كله عَبَث وبدون أي جدوى\n♡موقف رابع بيحكيه أنس بن مالك رضي الله عنه وبيقول:\nكان في أهل بيت من الأنصار عندهم جمل بيحملوا عليه المية عشان يسقوا الزرع، فجأة كده الجمل استصعب عليهم ومنعهم إنهم يحملوا على ظهره حاجة،\nوالجمل بصفة عامة إذا هاج محدش بيقدر يعمله حاجة وبيبقى مؤذي فعلا\nفجاءوا لرسول الله ﷺ وهو قاعد مع الصحابة وحكوا له عن الجمل إللي رافض إنهم يحملوا عليه الماء وإن الزرع والنخل عطشوا بسبب قلة الماء،\nفقال رسول الله ﷺ لأصحابه: \nقُومُوا.\nيعني تعالوا بينا نشوف إيه حكاية الجمل ده، فقاموا وراحوا البستان إللي كان فيه الجمل، وكان الجمل واقف في ناحية كده لوحده،\nفَمَشَى رسول الله ﷺ ناحية الجمل، فقال أصحاب الجمل لرسول الله ﷺ:\nيَا نَبِيَّ اللَّهِ إِنَّهُ قَدْ صَارَ مِثْلَ الْكَلْبِ الْكَلِبِ، وَإِنَّا نَخَافُ عَلَيْكَ صَوْلَتَهُ.\nيعني بيقولوا له إن الجمل بقى عامل زي الكلب المسعور إللي بيهجم على أي حد ويؤذيه، وهم خايفين على رسول الله ﷺ منه، فقال لهم رسول الله ﷺ:\nلَيْسَ عَلَيَّ مِنْهُ بَأْسٌ.\nيعني متخافوش عليّ منه مش هيقدر يعمل لي حاجة،\n\"فَلَمَّا نَظَرَ الْجَمَلُ إِلَى رَسُولِ اللَّهِ ﷺ أَقْبَلَ نَحْوَهُ حَتَّى خَرَّ سَاجِدًا بَيْنَ يَدَيْهِ\"\nيعني الجمل أول ما شاف رسول الله ﷺ جاء ناحيته وراح نازل بَارِك على الأرض ووضع شفته على الأرص بين يدي رسول الله ﷺ كأنه بيسجد؛ لأن السجود الحقيقي إللي احنا عارفينه الجمل ميقدرش يسجده\n \"فَأَخَذَ رَسُولُ اللَّهِ ﷺ بِنَاصِيَتِهِ أَذَلَّ مَا كَانَتْ قَطُّ، حَتَّى أَدْخَلَهُ فِي الْعَمَلِ\"\nيعني بقى مُذلل ومطيع جدا حتى أكثر الأول، فأخذه رسول الله ﷺ وأدخله في العمل وخلاه يشتغل الشغل بتاعه المعتاد،\nفهنا قال الصحابة إللي شافوا الموقف:\nيَا رَسُولَ اللَّهِ ! هَذِهِ بَهِيمَةٌ لَا تَعْقِلُ تَسْجُدُ لَك\nوَنَحْنُ نَعْقِلُ، فَنَحْنُ أَحَقُّ أَنْ نَسْجُدَ لَكَ\nيعني بيقولوا لرسول الله ﷺ إن البهيمة إللي متعرفش حاجة خالص ولا تعرف قيمتك بتسجد لك، فاحنا أحق منها بالسجود لك،\nفقال لهم رسول الله ﷺ:\n\"لَا يَصْلُحُ لِبَشَرٍ أَنْ يَسْجُدَ لِبَشَرٍ، وَلَوْ صَلَحَ لِبَشَرٍ أَنْ يَسْجُدَ لِبَشَرٍ لَأَمَرْتُ الْمَرْأَةَ أَنْ تَسْجُدَ لِزَوْجِهَا مِنْ عِظَمِ حَقِّهِ عَلَيْهَا\"\nيعني لا يجوز لبشر أن يسجد لبشر مهما كان، ولو حتى سجود تحية،\nولو حصل يعني وبقى جائز إن بشر يسجد لبشر، لكنت أمرت المرأة ان تسجد لزوجها، بسبب عظم حقه عليها.\n☆خدوا بالكم الكلام هنا كناية عن عظم حق الزوج على زوجته،\nمش عايزة حد يقولي ما هو في رجالة ظالمين ومش بينفقوا على زوجاتهم و....و...إلخ\nفإزاي يعني بعد كل ده يبقى حق الزوج يبقى عظيم والكلام ده\nلأن في قاعدة عامة رسول الله ﷺ وضعها وهي عظم حق الزوج على زوجته، كون بقى إن في أزواج مقصرين في النفقة على الزوجة، والرجل بيؤذي زوجته و....و....\nساعتها بقى لها نشوف حل لكل مشكلة، ونبدأ نصلح، والمرأة لها الحق إنها تفارق الزوج إذا كان واقع عليها ضرر شديد والزوج مستمر ومُصِر على خطأه،\nفأنا بتكلم عن أحكام الإسلام والحقوق إللي أعطاها للمرأة\nمليش دعوة بالواقع وإزاي نطبق والمصالح والمفاسد، الحاجات دي عايزة لها ناس متخصصة وتفصيل وده مش مجالنا هنا خالص\nأنا بس بوضح النقطة إللي جاءت في الحديث، عشان محدش يفكر إن الإسلام ظلم المرأة ومخلي الرجل متسلط عليها بالظلم والعدوان بدون أي مراعاة لحقها، زي ما ناس كتير فاهمة للأسف وعاملين على الموضوع شغلانة وهم إللي مش فاهمين حاجة أصلا\nآخر حاجة معانا النهاردة هو تنبيه على قصة بينقلها بعض الدعاة ولكنها لا تصح عن رسول الله ﷺ\n وهي قصة الغزالة:\n《القصة بتقول إن رسول الله ﷺ كان مرة في صحراء فسمع صوت بينادي عليه، فالتفت يشوف مين بينادي ملقاش حد،\nفقعد يدور على مصدر الصوت فلقى غزالة مُقيدة،\nفالغزالة قالت له قرّب مني يا رسول الله،\nفلما قرب منها سألها هي عايزة إيه،  فقالت له إن عندها طفلين صغيرين في الجبل، وطلبت منه إنه يفك قيودها عشان تروح ترضعهم وترجع للقيد مرة تانية،\nفقال لها: هتعملي كده فعلا؟ \nفقالت أيوة هرجع، فرسول الله ﷺ فك قيودها وراحت رضعت أبناءها ورجعت، فقيدها رسول الله ﷺ،\nفكان في أعرابي هو إللي مقيدها، فانتبه لوجود رسول الله ﷺ، فسأله إذا كان عايز حاجة،\nفطلب منه رسول الله ﷺ إنه يُطلق سراح الغزالة، فأطلق الأعرابي سراح الغزالة، فانطلقت وهي تقول:\nأَشْهَدُ أَنْ لا إِلَهَ إِلا اللَّهُ وَأَنَّكَ رَسُولُ اللَّهِ》\nالقصة مؤثرة بس للأسف لا تصح عن رسول الله ﷺ\n فكان لازم أنبه عليها عشان لو سمعتوها أو لقيتوا حد ناشرها تبقوا عارفين إنها غير صحيحة\nرزقنا الله وإياكم العلم النافع والعمل به \nوبكده يبقى احنا انتهينا من أهم الأحداث في السنة التاسعة من الهجرة، وإن شاء الله من المرة الجاية هنتكلم عن أحداث السنة العاشرة من الهجرة\n مصادر جزء النهاردة في التعليقات"}, {"n": 243, "l": "الجزء 217 | مسيلمه الكذاب", "u": "https://www.facebook.com/groups/710210019782034/permalink/837714733698228/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وسبعة_عشر\n#أحداث_السنة_العاشرة_من_الهجرة\n#مسيلمة_الكذاب\nشوفنا في أحداث السنة التاسعة من الهجرة النتائج العظيمة لغزوة تبوك وشوفنا الوفود إللي جاءت لرسول الله ﷺ لتعلن إسلامها،\nوشوفنا وصول الدولة الإسلامية لأقصى مراحل القوة والتمكين في عهد رسول الله ﷺ،\nلكن لكل شيء نهاية، ولكل أجل كتاب، ولكل قصة خاتمة،\nوالسنة العاشرة من الهجرة هي بداية النهاية وبداية الخاتمة في حياة رسول الله ﷺ \nومن رحمة ربنا بالصحابة إنه مهّد للنهاية دي بأحداث ومواقف وبعبارات كثيرة؛ عشان يهوّن على المسلمين مصيبتهم في موت رسول الله ﷺ، \nيعني فتح مكة وإسلام هوازن وثقيف وقدوم الوفود الكثيرة إلى المدينة كل ده علامة من علامات اقتراب الأجل، وإن مهمة رسول الله ﷺ قرّبت تنتهي\nوحتى كثير من أحداث السنة العاشرة من الهجرة فيها إشارات إن خلاص أَجَل رسول الله ﷺ قرّب ينتهي،\nوكمان حواره ﷺ مع معاذ بن جبل رضي الله عنه قبل ما يسافر لليمن كان إشارة واضحة على كده زي ما حكينا.\nهنبدأ نعرف بقى أهم الأحداث إللي حصلت في السنة العاشرة من الهجرة،\nلكن قبل ما نتكلم عن الأحداث في أخت سألت سؤال عن صحة قصة الضّب، وأنا كنت ناوية أنبه عليها لأن في دعاة بيذكروا القصة دي بس نسيت\nفسؤالها فكرني جزاها الله خيرا،\nقصة الضب إللي شهد لرسول الله ﷺ بالرسالة قصة منكرة غير ثابتة عن رسول الله ﷺ ولا تصح سندًا\nالقصة بتقول إن رجل أعرابي اصطاد ضَب، وعدّى على رسول الله ﷺ وهو قاعد مع مجموعة من أصحابه،\nفسأل عن مين إللي قاعد ده والناس مجتمعين عليه،\nفقيل له إنه رسول الله ﷺ،\nفتوجه لرسول الله ﷺ وعدّى من وسط الناس ووقف قصاد رسول الله ﷺ وقال له إنه مشفش حد أكذب من رسول الله ﷺ ولولا إنه خايف أحسن قومه يتهموه بإنه عَجُول من الاستعجال يعني وإنه مش حليم لقتل رسول الله ﷺ،\nفهنا عمر رضي الله عنه قال لرسول الله ﷺ خليني أقتله يا رسول الله، فرسول الله ﷺ هدّاه وقال له إنه يصبر،\nفالرجل الأعرابي قال لرسول الله ﷺ وَاللَّاتِ وَالْعُزَّى لَا آمَنْتُ بِكَ، أَوْ يُؤْمِنَ بِكَ هَذَا الضَّبُّ؟\nوراح مطلع الضب إللي معاه، فرسول الله ﷺ قال له لو الضب آمن بي، انت هتؤمن؟ فالأعرابي قال نعم، فرسول الله ﷺ كلم الضب وقال له: يَا ضَبُّ!!\nفَتَكَلَّمَ الضَّبُّ بِكَلَامٍ عَرَبِيٍّ مُبِينٍ، يَفْهَمُهُ الْقَوْمُ جَمِيعًا: لَبَّيْكَ وَسَعْدَيْكَ، يَا رَسُولَ رَبِّ الْعَالَمِينَ.\nفسأله رسول الله ﷺ انت بتعبد مين فالضب رد عليه إنه بيعبد الله، فسأله رسول الله ﷺ عن نفسه من هو فالضب رد عليه وقال له:\nأَنْتَ رَسُولُ رَبِّ الْعَالَمِينَ، وَخَاتَمُ النَّبِيِّينَ، قَدْ أَفْلَحَ مَنْ صَدَّقَكَ، وَقَدْ خَابَ مَنْ كَذَّبَكَ.\nفهنا الأعرابي قال: \n\" أَشْهَدُ أَنَّ لَا إِلَهَ إِلَّا اللَّهُ، وَأَنَّكَ رَسُولُ اللَّهِ حَقًّا\"\nالقصة جميلة ومؤثرة لكنها غير صحيحة عن رسول الله ﷺ\nوطبعا مينفعش نستشهد بيها؛ لأن ده من الكذب على رسول الله ﷺ، ورسول الله ﷺ قال:\n\" إنَّ كَذِبًا عليَّ ليس ككَذِبٍ على أحَدٍ، مَن كذَبَ عليَّ متعَمِّدًا فلْيَتبَّوأْ مَقعَدَه مِن النارِ\"\nوالوعيد ده لأن رسول الله ﷺ هو القُدوة للمسلمين في أقواله وأفعاله فالكذب عليه بيدخل في دين الله تعالى ما ليس منه، عشان كده الوعيد شديد للي بيكذب على رسول الله ﷺ\nنرجع بقى لأحداث السنة العاشرة من الهجرة \nفي بدايات السنة العاشرة من الهجرة رسول الله ﷺ أرسل خالد بن الوليد في سَرِية ومعاه أربعمائة واحد من الصحابة إلى بني الحارث بن كعب في نجران وأمره إنه يدعوهم إلى الإسلام لمدة ثلاثة أيام قبل ما يقاتلهم،\nفلو استجابوا لخالد وأسلموا خلاص يقبل منهم الإسلام ويقعد يعلمهم كتاب الله وسنّة نبيّه ومعالم الإسلام، \nلكن لو مستجابوش له فساعتها يقاتلهم،\nفخرج خالد رضي الله عنه بالسرية وتوجه لبني الحارث،\nفلما وصل أرسل مجموعة من إللي معاه يدعون للإسلام في كل أجزاء المنطقة ويقولوا للناس:\nأسلِمُوا تسلمُوا.\nفأسلم الناس ودخلوا في إللي دعاهم إليه، فأقام خالد فيهم يعلمهم الإسلام وكتاب الله وسنّة نبيّه،\nوبعدين كتب خالد رسالة إلى رسول الله ﷺ يحكي له إللي عمله ويبشّره إن الناس دخلت في الإسلام.\nوبعدين بقى جاء وفد بني الحارث بن كعب عشان يبايعوا رسول الله ﷺ على الإسلام، \nلكنهم هيرتدوا لما يخرج الأسود العَنْسِيُّ مُدّعي النبوة قبل موت رسول الله ﷺ بأربعة أشهر تقريبا، وهنعرف الأحداث إن شاء الله لما ييجي وقتها\nفي السنة العاشرة من الهجرة حصل حادث مهم جدا هيكون له أثر كبير بعد موت رسول الله ﷺ، وهيُقتل بسببه عدد كبير من الصحابة ومن حفظة القرآن\nإيه إللي حصل\nفاكرين في الجزء المائة واثنان وثلاثون لما كنا بنتكلم عن الرسائل إللي أرسلها رسول الله ﷺ للملوك بعد صُلح الحديبية، وقلنا إن رسول الله ﷺ أرسل رسالة لملك اليَمامة وكان اسمه هَوْذَة بن علي،\nولما قرأ الرسالة عرف إن رسول الله ﷺ هيظهر على العرب وكان عايز يبقى خليفة من بعد رسول الله ﷺ لكن رسول الله ﷺ رفض وقال باد وباد ملكه ومات هَوذة بعدها بسنتين\nأهه بني حنيفة دلوقتي جايين في وفد لرسول الله ﷺ مكوّن من أربعة عشر رجلا من وُجهائهم وأكابرهم عشان يعملوا زي مفاوضات كده مع رسول الله ﷺ وبعدين يعلنوا إسلامهم\n \nوكان في الوفد ده واحد اسمه مُسيْلِمة بن حبيب أو مُسيْلمة بن ثُمامة وواحد تاني اسمه الرجَّال أو الرحَّال بن عُنفُوَة، مسيلمة بن حبيب ده كان على قدرٍ من قوَّة البيان والشخصيَّة وكان بيعمل كتير من أعمال الدّجل والسحر،\nوكان له تأثير واضح في أوساط بني حنيفة والقبائل المجاورة، وكان اتسمى: رحمان اليمامة،\nوكان عمره لما جاء للمدينة مع الوفد أكثر من مائة وعشرين سنة\nلما جاء مسيلمة للمدينة مع قومه كان بيقول:\nإنْ جَعَلَ لي مُحَمَّدٌ الأمْرَ مِن بَعْدِهِ تَبِعْتُهُ\nيعني لو محمد ﷺ أوصى لي بالخلافة بعد ما يموت أنا هدخل في الإسلام وأبقى من اتباعه،\nوطبعا انتم عارفين رأي رسول الله ﷺ في الموضوع ده بالذات\nوعارفين إنه قال:\n\"إنا والله لا نُوَلّي هذا العمل أحداً سأله ولا أحداً حرص عليه\"\nالمهم،\nرسول الله ﷺ جاء لمسيلمة وهو قاعد مع أصحابه إللي جاء معهم، وكان مع رسول الله ﷺ ساعتها ثابت بن قيس بن شماس خطيب رسول الله ﷺ، فقال مسيلمة لرسول الله ﷺ:\n\"إنْ شِئْتَ خَلَّيْتَ بيْنَنَا وبيْنَ الأمْرِ، ثُمَّ جَعَلْتَهُ لَنَا بَعْدَكَ\"\nيعني بيساوم رسول الله ﷺ إنه يجعله هو الخليفة من بعده في مقابل إنه يدخل في الإسلام،\nوهو بيتكلم بقلب جامد كده لأن بني حنيفة من أضخم القبائل العربية وأوفرهم حظ من ناحية المَنعة والجَاه،\nفهو تخيّل بقى إن رسول الله ﷺ هيوافق عشان يكسب بني حنيفة في صفه\nرسول الله ﷺ كان في إيده ساعتها قِطْعَةُ جَرِيدٍ، يعني غصن من غصون النخل، فقال له رسول الله ﷺ:\n\"لو سَأَلْتَنِي هذِه القِطْعَةَ ما أعْطَيْتُكَهَا، ولَنْ تَعْدُوَ أمْرَ اللَّهِ فِيكَ، ولَئِنْ أدْبَرْتَ ليَعْقِرَنَّكَ اللَّهُ، وإنِّي لَأَرَاكَ الذي أُرِيتُ فِيكَ ما رَأَيْتُ\"\nيعني كأن رسول الله ﷺ بيقوله ده انت لو طلبت مني أديك غصن النخل إللي في إيدي ده مش هدهولك، تقوم تقولي أديك الخلافة من بعدي\nوبيقوله إنه مش هيتجاوز الحد إللي ربنا قدّره فيه وهو إنه مش هياخد إللي هو عايزه،\nوإنه لو امتنع عن اتباع رسول الله ﷺ ربنا هيُهلكه ويقتله، وإن نهايته وآخرته هتكون زي إللي رسول الله ﷺ شافه في الرؤيا\n☆إيه الرؤيا إللي رسول الله ﷺ شافها \nقال رسول الله ﷺ:\n\"بيْنَما أنَا نَائِمٌ، رَأَيْتُ في يَدَيَّ سِوَارَيْنِ مِن ذَهَبٍ، \nفأهَمَّنِي شَأْنُهُمَا، فَأُوحِيَ إلَيَّ في المَنَامِ:\nأنِ انْفُخْهُمَا، فَنَفَخْتُهُما فَطَارَا، فأوَّلْتُهُما كَذَّابَيْنِ، يَخْرُجَانِ بَعْدِي\"\nيعني رسول الله ﷺ بيقول وهو نايم شاف إنه لابس في إيده إسورتين من الذهب، فزعل واتضايق إنه لابس الذهب ده؛ لأن الذهب مُحرم على الرجال،\nفأخبره الوحي وهو نائم إنه ينفخ في الإسورتين دول، فنخفهم فسقطوا من إيده،\nففسر رسول الله ﷺ الإسورتين دول بإنهم رجلين كذابين هيخرجوا ويدّعوا النبوة وهتكون لهم قوة وشوكة بعد زمن رسول الله ﷺ، فكان الرجلين دول هما مسيلمة بن حبيب والأسود العَنْسِيُّ\nأسلم وفد بني حنيفة وأكرمهم رسول الله ﷺ وأعطاهم المكافآت، ورجعوا لقومهم ورجع معاهم مسيلمة بن حبيب.\n☆هل مسيلمة نفسه أسلم أو أظهر الإسلام وبعدين ارتد ولّا استمر على كفره لحد ما رجع لليمامة؛ الله أعلم\nفي علماء قالوا إنه أظهر الإسلام وبعدين ارتد لما رجع لقومه زي شيخ الإسلام ابن تيمية،\nوفي علماء قالوا لأ مفيش أي دليل على إسلامه، وحتى طريقة كلام رسول الله ﷺ معاه بتدل على إنه لم يسلم؛ \nلأن مش من عادة رسول الله ﷺ إنه يتكلم بالطريقة دي مع حد أسلم أو حتى مُظهر للإسلام وهو منافق،\nواحنا شوفنا طريقة تعامله ﷺ مع ابن سلول كانت عاملة إزي،\nفقالوا إن مسيلمة استمر على الكفر ولم يُظهر حتى الإسلام،\nفالموضوع على خلاف بين العلماء وكل واحد له أدلته،\nلكن احنا إللي يهمنا في الموضوع ده كله إن مسيلمة كافر وادّعى النبوة وخلاص\nفي الفترة إللي قعدها بنو حنيفة في المدينة الرجَّال أو الرحَّال بن عُنفُوَة إللي كان موجود مع الوفد انتهز الفرصة وقعد يتعلم القرآن ويتفقّه في الدين وكان رجل عنده ذكاء وبصيرة، فخلاه رسول الله ﷺ هو إللي يعلم أهل اليمامة الإسلام.\nلما رجع مسيلمة لليمامة ادّعى النبوة، وبنو حنيفة إللي كانوا أسلموا ارتدوا واتبعوه.\n☆ملحوظة هنا عشان الموضوع منتشر وابن كثير ذكره في البداية والنهاية،\nفي حديث عن رسول الله ﷺ بيقول إن في مرة رسول الله ﷺ عدّى على مجموعة قاعدين مع بعض كان فيهم أبو هريرة والرجَّال بن عُنفُوَة، فقال لهم رسول الله ﷺ:\n\"إِنَّ فِيكُمْ لَرَجُلاً ضَرْسُهُ فِي النَّارِ أَعْظَمُ مِنْ أُحُدٍ\"\nفكان أبو هريرة خايف على نفسه وخصوصا إن كل إللي كان قاعدين معاه ماتوا في سبيل الله ماعدا هو والرجَّال بن عُنفُوَة، \nفالقصة بتقول إن الرجَّال ده لما رجع لليمامة مسيلمة أغراه بالمُلك والمال وطلب منه إنه يقول للناس إن محمد ﷺ قال عن مسيلمة إنه رسول هو كمان،\nفوافق الرجَّال وارتد هو كمان وفتن الناس وأخبرهم إن رسول الله ﷺ قال إن مسيلمة رسول وأمر الناس باتباعه، وبكده بقى المقصود من الحديث إللي قاله رسول الله ﷺ هو الرجَّال بن عُنفُوَة، \nلكن يا جماعة الحديث ده أصلا غير صحيح ولا يثبت عن رسول الله ﷺ \nوقصة ارتداد الرجَّال بن عُنفُوَة عن الإسلام لم تأتِ بطريق صحيح، يعني كل الروايات إللي جاءت فيها قصة ارتداد الرجَّال بن عُنفُوَة هي روايات غير صحيحة، فمينفعش الاستشهاد بيها \nوهتلاقوا في التعليقات روابط لتفصيل المسألة للمهتمين بعلم الحديث\nطبعا الحديث إللي قلناه من شوية ده غير الحديث الصحيح إللي قاله أبو هريرة رضي الله عنه عن وصف الكافر في النار\nالحديث الصحيح بيقول:\n\"إن الرجل من أهل النار ليعظُم للنار، حتى يكون الضّرس من أضراسه كأحد\"\nيعني الكفار لما يدخلوا النار مش هيبقوا زي ما هم كده في حجمهم الطبيعي، لأ، ده هيبقى حجم جسمهم كبير جدا لدرجة إن حجم ضرس الواحد فيهم مثل جبل أحد كده والعياذ بالله\nالمهم بقى مسيلمة عاش الدور إنه نبي وبقى يؤلف كلام قال يعني زي القرآن كده\nوأرسل مسيلمة لرسول الله ﷺ رسالة بيقوله فيها:\n\"من مسيلمة رسول الله إلى محمَّدٍ رسول الله، \nسلام عليك فإنِّي قد أُشركت في الأمر معك، وإنَّ لنا نصف الأرض ولقريش نصف الأرض، ولكنَّ قريشًا يعتدون\"\nيعني مسيلمة بيقول لرسول الله ﷺ إنه رسول زيه زي النبي ﷺ، وربنا أعطى له نص الأرض يحكمها هو وبني حنيفة، \nوأعطى لرسول الله ﷺ ولقريش النص التاني،\nبس عشان قريش قوم معتدين وانت من قريش فانت هتعترض ومش هتوافق على التقسيمة،\nرسالة مسيلمة جاء بها رجلان من بني حنيفة  لرسول الله ﷺ، بعد ما رسول الله ﷺ سمع الكلام إللي في الرسالة قال للرجلين:\n ما تقولانِ أنتما؟\nيعني إيه هي عقيدتكم في مسيلمة وهل بتؤمنوا باللي بيقوله في ادِّعائهِ النُّبوَّةَ؟\nقالا: نقولُ كما قال.\nيعني احنا مؤمنين بيه ومصدقينه في كلامه، فقال لهما رسول الله ﷺ:\nأمَا واللهِ لولا أنَّ الرُّسلَ لا تُقتَلُ لضربتُ أعناقَكُما\nيعني لولا إن الرسل لا تُقتل لكان رسول الله ﷺ قتلهم؛ لأنهم إما كفار أو مرتدين عن الإسلام واحنا اتكلمنا عن آية السيف قبل كده،\nفهنا رسول الله ﷺ أمر بكتابة رسالة لمسيلمة وقال فيها:\n\" بسم الله الرحمن الرحيم، \nمِنْ مُحَمَّدٍ رَسُولُ اللهِ إِلَى مُسَيْلِمَةَ الْكَذَّابِ.\n سَلامٌ عَلَى مَنِ اتَّبَعَ الْهُدَى، أَمَّا بَعْدُ، فإِنَّ الْأَرْضَ لِلَّهِ يُورِثُهَا مَنْ يَشَاءُ مِنْ عِبادِهِ وَالْعاقِبَةُ لِلْمُتَّقِينَ\"\nيعتي انت كذاب وانت ولا انت رسول ولا حاجة، والأرض دي بتاعة ربنا يعطيها لمن يشاء من عباده، وهو وعدها لعباده المتقين مش الكذابين إللي زيك\nومن هنا بقى اتعرف مسيلمة باسم مسيلمة الكذاب،\nكان إيه رد فعل مسيلمة بعد ما وصلته رسالة رسول الله ﷺ؟\nده إللي هنعرفه الجزء الجاي إن شاء الله \nمصادر جزء النهاردة في التعليقات\n☆"}, {"n": 244, "l": "الجزء 218 | بداية ظهور الخوارج", "u": "https://www.facebook.com/groups/710210019782034/permalink/837716453698056/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وثمانية_عشر\n#أحداث_السنة_العاشرة_من_الهجرة\n#بداية_ظهور_الخوارج\nاتكلمنا المرة إللي فاتت عن ظهور مسيلمة الكذاب وشوفنا الرسالة إللي رسول الله ﷺ أرسلها له،\nلكن مسيلمة الكذاب ولا اهتم برسالة رسول الله ﷺ واستمر في كذبه وتضليله للناس،\nوكان عايز يُظهر كرامات تشبه معجزات رسول الله ﷺ، فأظهر الله كذبه\nمن الأمثلة إللي حصلت ما ذكره ابن كثير في البداية والنهاية، بيقول إن مسيلمة بصَق في بئر فغاضَ ماؤها، يعني البئر كان فيها مية قليلة فبصَق فيها قال يعني عشان تزيد راحت المية غابت في الأرض واختفت تماما\nوسقى بوضوئه نخلا فيبسَت، يعني هو اتوضى والمية إللي سقطت منه وهو بيتوضى سقى بيها نخل، النخل مات وبقى يابس ولا يُنتفع به، ودعا لرجل أصابه وجع في عينيه فمسحهما فعمِي،\nيعني جاءه رجل بيشتكي وجع في عينه فدعا له ومسح على عينه فبدل ما عينه تخف الراجل اتعمى\nوبدأ مسيلمة الكذاب يؤلف للناس كلام يضاهي به القرآن زي ما قلنا المرة إللي فاتت، زي مثلا:\n\" الفيل. الْفِيلُ وَمَا أَدْرَاكَ مَا الْفِيلُ، لَهُ زَلُّومٌ طَوِيلٌ، إِنَّ ذَلِكَ مِنْ خَلْقِ رَبِّنَا الْجَلِيلِ\"\nقال يعني بيقلد القرآن في:\n\"الْقَارِعَةُ ۩ مَا الْقَارِعَةُ ۩ وَمَا أَدْرَاكَ مَا الْقَارِعَةُ ۩ يَوْمَ يَكُونُ النَّاسُ كَالْفَرَاشِ الْمَبْثُوثِ ۩ وَتَكُونُ الْجِبَالُ كَالْعِهْنِ الْمَنْفُوشِ\"\n لكن طبعا انتم شايفين الكذب الواضح في كلامه والفرق الكبير جدا بين كلامه وبين القرآن كلام الله\nوعلى فكرة إللي كان بيشوفه وبيسمع كلامه كان بيبقى عارف إنه كذاب، لكن عصبيتهم خلتهم يمشوا وراه ويصدقوه ويؤمنوا به،\nوكان الواحد منهم يقول له:\n\" أشهد أنَّك لكذَّاب وأنَّ محمَّدًا صادق؛ ولكنَّ كذَّاب ربيعة أحبُّ إلينا من صادق مُضَر\"\nيعني أنا عارف ومتأكد إنك كذاب وإن محمد صادق، لكن عشان انت من فرع ربيعة يعني من أهلنا فاحنا هنسمع كلامك ونمشي وراك، أحسن من محمد ﷺ إللي من فرع مُضر،\nولو تفتكروا احنا قلنا قبل كده واحنا بنتكلم عن هوازن إن العرب بينقسموا بصفة عامة إلى قسمين رئيسيين: عدنانيين وقحطانيين، \nوالعدنانيون دول بينقسموا إلى فرعين: رَبِيعة، و مُضَر، \nوفرع مُضَر ينقسم إلى: إِليَاس و عَيْلاَن، \nوقبيلة قريش جاية من فرع إلياس، فطبعا بعيدة جدا عن فرع ربيعة، وكل ما الأنساب بعدت عن بعض زادت الحزازيات بين القبائل، فالعصبية بتاعتهم خلتهم يتبعوا واحد كذاب وهمّ عارفين إنه كذاب عشان بس هو منهم\nموضوع مسيلمة الكذاب ده استمر لحد خلافة أبي بكر الصديق رضي الله عنه وأرسل جيش لحربه، لحد ما قتله وحشِي بن حرب، زي ما هنشوف إن شاء الله واحنا بنتكلم عن الخلفاء إذا كان في العمر بقية\nلما انتشر أمر مسيلمة الكذاب بين الناس، وقعدوا يتكلموا عنه وده كان قبل ما مسيلمة يرسل الرسالة لرسول الله ﷺ وقبل ما رسول الله ﷺ يرد على رسالته، قام رسول الله ﷺ يخطب في الناس وقال لهم:\n\" أما بعد، ففي شأن هذا الرجل الذي قد أكثرتم فيه، وإنه كذاب من ثلاثين كذابا ، يخرجون بين يدي الساعة\"\nيعني مسيلمة كذاب وهيخرج غيره ثلاثون كذابا قبل قيام الساعة يدعوا النبوة،\nواحنا اتكلمنا عن الموضوع ده واحنا بنشرح علامات الساعة\nفي قصة بيحكيها ابن كثير وبيرويها كثير من المفسرين وهي قصة حبيب بن زيد،\nبيقولوا إن رسول الله ﷺ في آخر حياته أرسل رسالة مع حبيب بن زيد لمسيلمة الكذاب عشان يخوّفه بالله يمكن يبطل إللي بيعمله ده،\nوحبيب بن زيد ده يبقى ابن أم عمارة 《نُسَيْبة بنت كعب》 \nإللي كانت في غزوة أحد تُطبب الجرحى وتسقيهم الماء،\nوإللي قعدت تحارب وتدافع عن رسول الله ﷺ لما سقط  في الحفرة وكان عمّال بينزف لو تفتكروا\nوكان حبيب بن زيد من الناس إللي حضرت بيعة العقبة الثانية وحضر غزوة أحد والخندق وغير من الغزوات،\nفاختاره رسول الله ﷺ ليحمل رسالته إلى مسيلمة الكذاب،\nلما وقف حبيب بن زيد عند مسيلمة وأعطاه رسالة رسول الله ﷺ قال له مسيلمة:\nأَتَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللهِ؟\nفقال حبيب: نعم.\nفقال له مسيلمة:\nأَتَشْهَدُ أَنَّى رَسُولُ اللهِ؟\nفقال حبيب: لا أسمع.\nفقال له مسيلمة: أتسمع هذا، ولا تسمع ذاك؟\nيعني انت بتسمع إللي على مزاجك، سمعت الأولى ومسمعتش التانية، فقال له حبيب: نعم.\nفقعد مسيلمة لعنه الله يقطع في أعضاء جسد حبيب بن زيد رضي الله عنه عضو عضو لحد ما قتله\nشوفتوا الفرق بين تعامل رسول الله ﷺ مع الرسل وتعامل غيره\nوالرواية التانية بتقول إن مسيلمة الكذاب أسر حبيب بن زيد بعد موت رسول الله ﷺ لما كان حبيب راجع من اليمن وحصل بينهم الحوار إللي قلنا عليه، لكن الرواية الأولى هي الأصح،\nلكن في الحالتين إللي قتل حبيب بن زيد رضي الله عنه هو مسيلمة الكذاب وقتله بالطريقة البشعة دي، لعنه الله\nهنسيب مسيلمة الكذاب وإللي بيعمله ونرجع لرسول الله ﷺ ونشوف باقي الأحداث إللي حصلت في السنة العاشرة من الهجرة،\nأرسل رسول الله ﷺ خالد بن الوليد لقبيلة همدَان في اليمن يدعوهم إلى الإسلام فلم يستجيبوا له، \nفأرسل رسول الله ﷺ علي بن أبي طالب رضي الله عنه بدل خالد وقال له يقول لخالد يرجع للمدينة وأي حد من الجنود إللي موجودين مع خالد عايز يكمل مع علي رضي الله عنه  يخليه معاه، \nوإللي عايز يرجع مع خالد للمدينة يرجع،\nفرجع خالد للمدينة مع مجموعة من الصحابة ومجموعة تانية قعدت مع علي رضي الله عنه في اليمن،\nبدأ علي رضي الله عنه الدعوة في قبيلة همدَان لحد ما أسلموا كلهم، \nوأرسل علي رضي الله عنه لرسول الله ﷺ في المدينة قطعة من الذهب لم تُحَصَّل من تُرَابِها، يعني لسه بترابها ومليانة شوائب ومش ذهب خالص يعني،\nأرسلها مع واحد من الصحابة،\nفلما وصلت له قطعة الذهب كان عنده مجموعة من سادات العرب، منهم الأقرع بن حابس وواحد تاني اسمه:\n《زيد الخَيْل》\nوزيد الخيل ده اسمه الحقيقي زيد بن مُهَلهَل، واتسمى زيد الخيل عشان كان عنده خيل كثيرة جدا وكان شاعر مشهور من قبيلة طَيء،\nفجاء للمدينة مع مجموعة من قومه عشان يتكلموا مع رسول الله ﷺ ويعرفوا عن الإسلام،\nفسمع زيد الخيل عن الإسلام من رسول الله ﷺ فأسلم، وسأله رسول الله ﷺ عن اسمه قال له إن اسمه زيد الخيل، فسمّاه رسول الله ﷺ:《زيد الخير》.\nودايما لما حد بيذكر قصة زيد الخير بيقول معاه قول رسول الله ﷺ عنه:\n\" ما ذُكر لي رجلٌ من العَربِ إلَّا رأيتُه دونَ ما ذُكر لي ؛ إلَّا ما كان مِن زيدٍ ؛ فإنَّه لم يبلغ كلَّ ما فيهِ\"\nمعنى الكلام إن لما حد من العرب يتوصف لرسول الله ﷺ وبعد كده يقابله كان بيبقى أقل من الوصف، يعني الناس بيكونوا مبالغين فيه، إلا زيد الخيل، طلع يستحق أكثر من الكلام إللي اتقال عنه،\nلكن الحديث ده طلع موضوع ولا يصح عن رسول الله ﷺ \nفاللي نعرفه وصحيح إن رسول الله ﷺ غيّر اسم زيد الخيل إلى زيد الخير، أما المقولة إللي قالها عنه دي فهي غير صحيحة\nالمهم بقى، لما كان زيد الخير موجود عند رسول الله ﷺ جاءت قطة الذهب إللي أرسلها علي بن أبي طالب رضي الله عنه من اليمن، فقسمها رسول الله ﷺ على أربعة رجال، منهم زيد الخير والأقرع بن حابس،\nوكان هدف رسول الله ﷺ من القسمة دي إن إللي أسلم فيهم يثبّت قلبه على الإسلام، أما إللي لسه بيشاور نفسه فيكون ده تشجيع له على الدخول في الإسلام،\nلكن واحد من المسلمين قال:\n\"كُنَّا نَحْنُ أحَقَّ بهذا مِن هَؤُلَاءِ\"\nيعني احنا إللي من حقنا ناخد الذهب ده مش الناس إللي لسه داخلة في الإسلام دي بعد ما خلاص أمر الإسلام استقر،\nوقطة الذهب دي كانت من الخُمس إللي يجوز لرسول الله ﷺ يتصرف فيه زي ماهو شايفه مناسب، واحنا اتكلمنا عن الموضوع ده بالتفصيل في توزيع غنائم حنين\n كلام الرجل وصل لرسول الله ﷺ، فقال:\n\" ألَا تَأْمَنُونِي وأَنَا أمِينُ مَن في السَّمَاءِ، يَأْتِينِي خَبَرُ السَّمَاءِ صَبَاحًا ومَسَاءً\"\nيعني ربنا مستأمنّي على الرسالة إللي أرسلني بها إلى الأرض وانت أيها المعترض وإللي على نفس رأيك مش قادرين تستأمنوني على حُطام الدنيا أن أضعه حيث يجب أن يُوضع كما يريد الله\nفقام رجلٌ غائِرُ العَيْنَيْنِ، مُشْرفُ الوَجْنَتين، ناشِزُ الجَبْهة، كَثُّ اللِّحيَة، مَحْلُوقُ الرَّأس، مُشَمَّر الإزار، فقال:\n\" يا رسولَ الله اتَّق الله\"\nيعني وهمّ عالحال ده قام رجل مِن بَني تَمِيمٍ يُقال له: ذو الْخُويصِرة واسمُه حُرْقُوص بن زُهَيْر، عينيه داخلة لجوة وعظم خده بارز، \nوجبهته كبيرة وطالعة لبرة، حالق شعره تماما وعنده لحية كثيرة الشعر وهو ضخم الجسم، ثوبه مرتفع أعلى من الكعبين، راح قايم وقايل لرسول الله ﷺ خاف ربنا يا رسول الله، انت إزاي تقسم التقسيمة دي، مش خايف أحسن ربنا يحاسبك بسبب معصيتك دي\nطبعا هنا رسول الله ﷺ رد عليه وقال له:\n\"وَيْلَك، أَوَلَسْتُ أحقَّ أهل الأرض أن يتقيَ الله\"\nيعني رسول الله ﷺ بيقول إن هو أَوْلى الناس وأحقهم بتقوى الله، يعني مين إللي هيتقي الله إذا رسول الله ﷺ لم يتقِّ الله\nفمن الضلال المبين إن الإنسان يتصور الطاعة بقت معصية،\nفالرجل المعترض ده تصور طاعة رسول الله ﷺ معصية، فعمل نفسه حاكم بقى على رسول الله ﷺ يأمره بالتقوى\nمع إن إللي رسول الله ﷺ بيعمله هو عين التقوى وعين الطاعة لله\nعشان كده خالد بن الوليد رضي الله عنه قال في ساعتها لرسول الله ﷺ:\n\"يا رَسولَ اللَّهِ، ألَا أضْرِبُ عُنُقَهُ؟\"\nيعني أقتله يا رسول الله ونخلص منه وخلاص؟\nفقال له رسول الله ﷺ:\n\"لا، لَعَلَّه أنْ يكون يُصَلِّي\"\nيعني رسول الله ﷺ رفض قتل ذو الْخُويصِرة لأن ظاهره إنه مسلم، ومينفعش قتل حد ظاهره الإسلام، ده غير كده هتنتشر إشاعة إن محمد ﷺ يقتل أصحابه\nفقال له خالد رضي الله عنه:\n\"وكَم مِن مُصَلٍّ يقول بلسانِه ما ليس في قلبِه\"\nيعني خالد بيقول إن في ناس كتير أوي ظاهرهم إنهم بيصلوا لكن قلوبهم مليانة كفر ونفاق وخديعة\nفقال له رسول الله ﷺ قاعدة مهمة جدا\n\"إني لم أومَرْ أنْ أُنَقِّبَ عن قلوب الناس ولا أَشُقَّ بطونَهم\"\nيعني رسول الله ﷺ بيقول إن ربنا أمره بإنه يعامل الناس على حسب ظاهرهم، أما بواطنهم وإللي مخبيينه فدي ملوش دعوة بيها، دي حاجة ربنا هو إللي يحاسب عليها\n☆وطبعا هنا لازم نقف وقفة مهمة\nكلام رسول الله ﷺ قاعدة عامة يا جماعة، يعني احنا ملناش غير الظاهر،\nفلو واحد ظاهره الكفر وعايش على الكفر لحد آخر لحظة في حياته فده ظاهره عندنا إنه كافر، \nيعني لا هنصلي عليه ولا ندفنه في مقابر المسلمين ولا نترحم عليه ولا ندعي له بالمغفرة، ومصيره إلى النار\nطب نفرض إنه مات على الإسلام واحنا منعرفش أو إنه تاب في آخر لحظة في حياته\nخلاص يبقى دي مش بتاعتنا، ربنا هو إللي هيحاسبه ساعتها على إللي في قلبه زي ما رسول الله ﷺ قال،\nربنا لم يأمرنا إننا نفتش في قلوب الناس عشان نعرف جواهم إيه\nوكذلك برده لو واحد عايش على الإسلام وظاهره إنه مسلم لحد آخر لحظة في حياته، \nيبقى ده نصلي عليه وندعي له بالرحمة ويُدفن في مقابر المسلمين، طيب نفرض يعني إنه كَفر في آخر لحظة من حياته، أو هو كان منافق ومحدش يعرف\nبرده ملناش دعوة مادام احنا منعرفش والرجل ظاهره الإسلام، إللي في القلوب ربنا هيحاسب عليه يوم القيامة\nفعشان بس مش كل شوية لما واحد كافر يموت الناس تقعد تترحم عليه وتقول مش يمكن أسلم في آخر لحظة\nأيوة يمكن بس احنا في الإسلام مش بنحط قواعد على الاحتمالية، لازم يكون عندنا يقين عشان نعرف هنتصرف إزاي؛\nلأن كل حاجة في حياتنا لها أحكام، فلو واحد مات على الإسلام له أحكام\nولو مات على الكفر له أحكام تانية خالص،\nفتخيلوا كده لما نقعد شاكين يا ترى هو مات على الكفر زي ما هو ظاهر لنا، ولّا هو أسلم في سره\nفهنعمل إيه بقى هنا، هل نترحم عليه يمكن أسلم، وفي نفس الوقت ندفنه في مقابر الكفار ومحدش يصلي عليه،\nولّا هنعمل إيه بالضبط في اللخبطة دي\nأهه ربنا عز وجل رحمنا من كل ده ووضع لما شريعة مُحكمة وقواعد معينة من غير أي لخبطة،\nأي حد يموت وهو ظاهره الكفر يبقى ده كافر قولا واحدا تجري عليه أحكام الكفار وخلِصنا\nولو هو غير الظاهر ده ربنا هيرحمه ويدخله الجنة، \nماهو يا جماعة ربنا مش مستني دعاءنا عشان يدخّله الجنة يعني\nوهو لو كافر وكل الخلق إنس وجن وملائكة وحيوانات و...و...دعوا له إن ربنا يرحمه والله ما هيرحمه خلاص انتهى الموضوع طول ما هو مات على الكفر\nيعني متفكروش كده إننا ممكن نتحايل على ربنا شوية فلما يلاقي إلحاحنا فهيقول خلاص هرحمه عشان خاطر دعاءكم مثلا\nده ربنا ياجماعة، مش واحد من البشر ممكن تتحايل عليه فيغير رأيه، وإلا كده الموضوع هيبقى فوضى\nربنا قال:\n\"مَا يُبَدَّلُ الْقَوْلُ لَدَيَّ وَمَا أَنَا بِظَلَّامٍ لِّلْعَبِيدِ\"\nفاحنا ملناش غير الظاهر نتعامل بيه، ظاهره الكفر يبقى نعامله في الدنيا معاملة الكفار، \nظاهره الإسلام يبقى نعامله في الدنيا معاملة أهل الإسلام، \nبس خدوا بالكم\nمش معنى إن فلان ظاهره إنه مات على الكفر أو ظاهره إنه مات على الإسلام يبقى كده نقول إنه أكيد هيدخل النار أو أكيد إنه هيدخل الجنة\nدي مش بتاعتنا بقى،\nاحنا لينا الأحكام بس في الدنيا، لكن أحكام الآخرة ونقعد ندخّل ده الجنة وده النار فده كده إللي مينفعش بقى، دي إللي يحكم فيها ربنا فقط\nإلا طبعا لو حد احنا عارفين على وجه اليقين إن فلان في النار أو في الجنة عن طريق الوحي،\nزي مثلا إبليس، وزي أبو لهب وأبو طالب وعمرو بن لُحي وغيرهم من إللي رسول الله ﷺ أخبر عنهم إنهم في النار، أو في الجنة زي أبو بكر الصديق وعمر بن الخطاب وعثمان وعلي وغيرهم من الصحابة\nأما بقى غير كده فاحنا منقولش على فلان الفلاني إنه هيدخل النار أو هيدخل الجنة حتى لو كان ظاهره إنه مات على الكفر، يارب تكون النقطة دي واضحة لأنها مهمة جدا في عقيدتنا كمسلمين\nوعمر بن الخطاب رضي الله عنه لخص لنا الموضوع ده في كلمتين بعد موت رسول الله ﷺ، \nقال عمر رضي الله عنه:\n\"إِنَّ أُنَاسًا كَانُوا يُؤْخَذُونَ بِالْوَحْيِ فِي عَهْدِ رَسُولِ الله ﷺ،\n وَإِنَّ الْوَحْيَ قَدْ انْقَطَعَ، وَإِنَّمَا نَأْخُذُكُمْ الآنَ بِمَا ظَهَرَ لَنَا مِنْ أَعْمَالِكُمْ ،\nفَمَنْ أَظْهَرَ لَنَا خَيْرًا أَمِنَّاهُ وَقَرَّبْنَاهُ، وَلَيْسَ إِلَيْنَا مِنْ سَرِيرَتِهِ شَيْءٌ ، اللَّهُ يُحَاسِبُهُ فِي سَرِيرَتِهِ ، \nوَمَنْ أَظْهَرَ لَنَا سُوءًا لَمْ نَأْمَنْهُ وَلَمْ نُصَدِّقْهُ ، وَإِنْ قَالَ إِنَّ سَرِيرَتَهُ حَسَنَة\"\nيعني الوحي إللي كان بيخبرنا بالسرائر خلاص انقطع، ودلوقتي ملناش غير الظاهر فاللي هيظهر لنا الخير هنقربه، وإللي هيظهر لنا الشر مش هنقربه ولا هنصدقه حتى لو قال أنا قلبي زي البَفْتة البيضا\nحلو الكلام\nنرجع بقى لرسول الله ﷺ بعد ما قال لخالد:\n\"إني لم أومَرْ أنْ أُنَقِّبَ عن قلوب الناس ولا أَشُقَّ بطونَهم\"\nلما الراجل مشي خلاص رسول الله ﷺ نظر ناحيته وقال لخالد بن الوليد رضي الله عنه:\n\"إنه يخرج من ضِئضِئ هذا قومٌ يتلونَ كتابَ اللهِ رَطْبًا،\nلا يجاوز حناجرَهم، يَمْرُقون من الدين كما يَمْرُق السَّهْمُ مِن الرَّمِيَّة، لئن أدركتُهم لأقتلنَّهم قَتْلَ ثمودَ\"\nيعني شايف الراجل إللي اعترض علي ده وقال لي اتقي الله، أهه هيخرج ناس من نوعية الراجل ده وهيمشوا على نفس منهجه، ومن صفات الناس دي إنهم بيقرأوا القرآن بكل سهولة لكثرة قراءتهم وحفظهم له، \nولكن القرآن لا يصل إلى قلوبهم ولا بيأثر فيهم؛ لأنهم مش بيفهموه ولا بيطبقوه زي ما ربنا أراده،\nوعشان كده بيخرجوا من الدين بسرعة وبسهولة كأنهم مدخلوش فيه أصلا وده لأن الإيمان لم يستقر في قلوبهم،\nوبسبب سوء فهمهم للدين هيقتلوا أهل الإسلام ويتركوا الكفار إللي بيعبدوا الأصنام\nفرسول الله ﷺ قال لخالد إنه لو عاش لحد ما يخرجوا هيقتلهم قتل شديد لحد ما يخلص عليهم كلهم وميتبقاش منهم حد زي ما ربنا أفنى قوم عاد\nوكان أول بداية ظهور للفرقة إللي وصفها رسول الله ﷺ في آخر خلافة عثمان بن عفان رضي الله عنه، \nوفي خلافة علي رضي الله عنه ظهروا بقوة وعملوا مشاكل كتير وبقى اسمهم الخَوَارِج، \nوطبعا ده كان من معجزات رسول الله ﷺ إنه أخبر عن حاجة هتحصل بعد موته بسنين \nإن شاء الله المرة الجاية هنكمل باقي الأحداث إللي حصلت في السنة العاشرة من الهجرة \nمصادر جزء النهاردة في التعليقات"}, {"n": 245, "l": "الجزء 219 | موت ابراهيم وكسوف الشمس", "u": "https://www.facebook.com/groups/710210019782034/permalink/837717000364668/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وتسعة_عشر\n#أحداث_السنة_العاشرة_من_الهجرة\n#موت_إبراهيم_وكسوف_الشمس\nهنكمل إن شاء الله النهاردة أحداث السنة العاشرة من الهجرة\nمن الأحداث إللي حصلت هي إسلام الصحابي جَرِير بن عبد الله البَجَلِيُّ، \nالأول كده، في خلاف كبير بين العلماء على زمن إسلامه\nفي إللي قال إنه أسلم سنة تسع للهجرة، وفي إللي قال إنه أسلم في رمضان سنة عشر للهجرة، وفي إللي قال إنه أسلم قبل كده بكتييير\nفاحنا إللي يهمنا إنه أسلم ويهمنا إللي رسول الله ﷺ أمره به، تمام كده\nبيحكي جرير وبيقول إنه لما جاء المدينة عشان يُسلم ومعاه خمسين رجل من قومه؛ دخل المسجد وكان رسول الله ﷺ بيخطب في الناس، فأول ما دخل المسجد كل الناس بصوا عليه فجأة،\nفعرف إن رسول الله ﷺ قال لهم حاجة عليه، فسأل الرجل إللي قاعد جنبه:\nهل ذكر رسول الله ﷺمن أمري شيئاً؟\nيعني هل رسول الله ﷺ قال لكم عني حاجة، فقال له الرجل: نعم، ذَكَرَكَ بِأَحْسَنِ الذِّكْرِ قال:\n\"إِنَّهُ سَيَدْخُلُ عَلَيْكُمْ مِنْ هَذَا الفَجِّ مِنْ خَيْرِ ذِي يَمَنٍ، أَلاَ وَإِنَّ عَلَى وَجْهِهِ مِسْحَةَ مَلَكٍ\"\nيعني هيدخل عليكم من الناحية دي رجل من خير أهل اليمن  وعليه جمال ظاهر، \nوكان من جمال جرير بن عبد الله البَجَلِيُّ إن عمر رضي الله عنه كان بيقول عنه إنه يوسف هذه الأمة\nفلما سمع جرير الكلام حمد الله على النعمة إللي وهبها له،\nوقال جرير:\n\"ما حَجَبَنِي النبيُّ ﷺ مُنْذُ أسْلَمْتُ، ولَا رَآنِي إلَّا تَبَسَّمَ في وجْهِي\"\nيعني بيقول إن مفيش مرة رسول الله ﷺ رفض إنه يقابل فيها جرير بن عبد الله لما كان يروح له البيت،\nكل مرة يستأذن عليه جرير كان رسول الله ﷺ يأذن له، ومفيش مرة رسول الله ﷺ يشوف فيها جرير إلا تبسم في وجه جرير،\nوبالمناسبة يا جماعة جرير هو راوي الحديث بتاع حكم نَظر الفَجأة\nيعني هو في مرة سأل رسول الله ﷺ عن نظرة الفجأة، يعني يبقى ماشي وفجأة يشوف حاجة مُحرمة، أو يشوف امرأة بدون قصد،\nفسأل رسول الله ﷺ يعمل إيه في موقف زي ده، فقال له رسول الله ﷺ: \nاصرف بصرك، يعني لو وقعت عينك على شيء محرم متكملش نظر، على طول اصرف بصرك وبكده مش هيبقى عليك ذنب\nقال له رسول الله ﷺ في مرة:\nألَا تُرِيحُنِي مِن ذِي الخَلَصَةِ؟\nو ذِي الخَلَصَةِ ده بيت في اليمن كان بيُشرَك فيه بالله وكان له اسم تاني هو الكعبة اليمانية،\nوإللي كان بيعبدوه قبيلة خَثْعَمَ وبَجِيلَةَ قبيلة جرير، وكان فيه نُصُبٌ، يعني كان فيه حجارة يذبحون عليها لغير الله، \nفرسول الله ﷺ كان مهموم إن لسه في مكان يُشرك فيه بالله، فكان عايز يرتاح من الهم ده، \nومكنش في شيء أتعب لقلب رسول الله ﷺ من إن يبقى في شيء يُعبد من دون الله تعالى\nفطلب من جرير بالذات إنه يخلصه من الصنم ده لأنه كان في بلاد قومه وهو كان من أشرافهم وقبيلته كانت بتعبده مع قبيلة خَثعم،\nفاستجاب جرير لطلب رسول الله ﷺ على طول وقال: بَلَى.\nلكن جرير كان عنده مشكلة وهي إنه مش بيثبت على فرس، \nيعني لأنه كان خفيف فكان بيرتفع عن السّرج إللي بيكون على الحصان كل ما ارتفع الحصان ويهبط بهبوط الحصان،\nوطبعا ده فيه خطر عليه لأنه ممكن يقع،\nفجرير بيقول إنه اشتكى لرسول الله ﷺ إنه لا يثبت على فرس، فضرب رسول الله ﷺ بيَدِهِ في صَدْرِ جرير، وقالَ: اللَّهُمَّ ثَبِّتْهُ واجْعَلْهُ هَادِيًا مَهْدِيًّا.\nيعني رسول الله ﷺ خبط على صدر جرير كده خبطة خفيفة ودعا له بالهداية والثبات على الفرس، \nفقال جرير إن من بعد دعاء رسول الله ﷺ له موقعش من على فرس تاني أبدا\nتوجه جرير مع مائة وخمسين رجل من قبيلة أحْمَسَ إلى ذِي الخَلَصَةِ عشان يهدموه، فلما وصل جرير لذِي الخَلَصَةِ هدم المبنى وحرق الخشب بتاعه،\nفأرسل جرير رجل لرسول الله ﷺ في المدينة يبشره بزوال ذِي الخَلَصَةِ، فلما وصل الرجل وبشّر رسول الله ﷺ؛ دعا رسول الله ﷺ بالبركة لخيل ورجال قبيلة أحْمَسَ خمس مرات.\nمن الأحداث إللي حصلت في السنة العاشرة للهجرة وتحديدا في شهر ربيع الأول: موت إبراهيم بن رسول الله ﷺ\nوكان ساعتها عمره ثمانيةَ عَشَرَ شهرا، \nيعني يا جماعة لحد آخر سنة في حياة رسول الله ﷺ والابتلاء الشديد مُلازم له\nرسول الله ﷺ مات أبناؤه كلهم في حياته ما عدا فاطمة رضي الله عنها، \nوكان آخر أبنائه موتا هو إبراهيم، وكان ساعتها رسول الله ﷺ قريب من الثلاثة وستين عام،\nفكان الموضوع شديد جدا على رسول الله ﷺ ولكن مع ذلك  استقبل رسول الله ﷺ الابتلاء ده باليقين والصبر والرضا بقضاء الله عز وجل،\nيقول أنس بن مالك رضي الله عنه إنه دخل مع رسول الله ﷺ على إبراهيم لما كان بيموت، يعني في النزع الأخير فلما شافه رسول الله ﷺ بكى، \nوكان معاهم عبد الرحمن بن عوف رضي الله عنه، فقال لرسول الله ﷺ:\n\" وأَنْتَ يا رَسولَ اللَّهِ؟\"\nيعني بيقول له إن الناس لا يصبِرون عند المصائب، وأنت يا رسولَ الله بتعمل زيهم وتبكي مع إنك دايما تكلمنا عن الصبرِ وتشجعنا عليه وتنهانا عن الجزعِ؟ \nفقال له رسول الله ﷺ:\n\"يا ابْنَ عَوْفٍ إنَّهَا رَحْمَةٌ\"\nيعني دي رقَّةٌ في القلبِ، بتحصل في النَّفس عند فِراقِ الأحبَّة، فتؤدي إلى حُزنِ القلبِ، وبكاءِ العين، وهي غريزةٌ في البشر لا يُلامُ عليها، وهي مش مِن الجزعِ،\nفالبكاءُ على المصيبةِ غريزةٌ إنسانيَّةٌ لا يأثَمُ عليها الإنسان مادام مفيش سَخَطٌ أو نُواح أو عدمُ رضًا بقضاءِ الله وقدَرِه\nواستمرت الدموع تنزل من عين رسول الله ﷺ، وقال:\nإنَّ العَيْنَ تَدْمَعُ، والقَلْبَ يَحْزَنُ، ولَا نَقُولُ إلَّا ما يَرْضَى رَبُّنَا، وإنَّا بفِرَاقِكَ يا إبْرَاهِيمُ لَمَحْزُونُونَ.\nيعني بسبب الغريزة إللي ربنا فطر الناس عليها فالعين بتدمع والقلب بيحزن، \nلكن في نفس الوقت لا نقولُ إلَّا ما يُرضي ربَّنا مِن الحمدِ والاسترجاعِ، وسؤالِ الخلَفِ الصَّالح،\nوإنَّا بفِراقِك يا إبراهيمُ لَمحزونونَ يعني: \nالحزن ده مش بإيدينا لكنه شيء ربنا جعله فينا وأوقَعه في قلوبنا، فلا نُلامُ عليه إلَّا إذا قُلْنا أو فعَلْنا ما لا يُرضي ربَّنا.\n☆وطبعا رسول الله ﷺ هنا في الموقف ده بيعلمنا إنَّ المؤمنَ  عند المصيبةِ لا يقولُ ولا يفعَلُ إلَّا ما يُرضي اللهَ عزَّ وجلَّ\nإبراهيم بن رسول الله ﷺ مات قبل تمام فترة الرضاع عشان كده هو له مرضعة تكمل رضاعه في الجنة زي ما قال رسول الله ﷺ:\n\"إنَّ له مُرْضِعًا في الجَنَّةِ\"\n☆طيب إيه الحكمة من موت أولاد رسول الله ﷺ الذكور من صغرهم كده\nلو تفتكروا في قصص الأنبياء هتلاقوا إن إبراهيم عليه السلام اتولد له ولدين هما إسماعيل وإسحاق،\nوهم الاتنين ورثوا النبوة عن إبراهيم عليه السلام، وكمان يعقوب ورث النبوة عن إسحاق وورثها يوسف عن يعقوب،\nوتوالت وراثة النبوة في بني إسرائيل، فورث سليمان داود وورث يحيى أبيه زكريا،\nوكان عيسى عليه السلام آخر أنبياء بني إسرائيل وبكده انتهت النبوة في فرع إسحاق عليه السلام،\nوانتقلت لفرع إسماعيل بدعوة إبراهيم عليه السلام لما قال:\n\"رَبَّنَا وَابْعَثْ فِيهِمْ رَسُولًا مِّنْهُمْ يَتْلُو عَلَيْهِمْ آيَاتِكَ وَيُعَلِّمُهُمُ الْكِتَابَ وَالْحِكْمَةَ وَيُزَكِّيهِمْ \"\nفرسول الله ﷺ هو دعوة إبراهيم عليه السلام زي ما قال في الحديث:\n\"أَنَا دَعْوَة أَبِي إبْرَاهِيم\"\nفبقت العادة في الغالب أن يَرث أبناء الأنبياء النبوّة من آبائهم،\nفلو كان لرسول الله ﷺ ولد من بعده كان هيبقى فتنة للناس لأنهم هيفكروا إن النبوة هيرثها أحد أبناء رسول الله ﷺ،\nورسول الله ﷺ هو خاتم الأنبياء والمرسلين ومفيش أي نبي بعده،\nوفعلا ظهرت الحكمة من ده بعد موت رسول الله ﷺ، \nلما انتقل الصحابة لنظام الخلافة بدل ما يكون في توريث النبوة زي الأمم السابقة زي ما قلنا\nفي نفس اليوم بقى إللي مات فيه إبراهيم بن رسول الله ﷺ حصل كسوف للشمس، فالناس ربطت بين موت إبراهيم وبين كسوف الشمس، فصلى رسول الله ﷺ صلاة الكسوف وبعد الصلاة وضّح لهم وقال:\n\" إِنَّ الشَّمْسَ وَالْقَمَرَ مِنْ آيَاتِ اللهِ،\nوَإِنَّهُمَا لَا يَنْخَسِفَانِ لِمَوْتِ أَحَدٍ، وَلَا لِحَيَاتِهِ، فَإِذَا رَأَيْتُمُوهُمَا فَكَبِّرُوا، وَادْعُوا اللهَ وَصَلُّوا وَتَصَدَّقُوا\"\nكان أهل الجاهلية يعتقدون بتأثير الشمس والقمر والنجوم، في الحوادث الأرضية، وأنها تنكسف إذا وُلد عظيم، أو مات عظيم، فهو هنا بيقول لهم إن الشمس والقمر من خَلق الله، \nمش بيتأثروا غير بأوامر ربنا،\nفلما يحصل لهم كسوف أو خسوف فده بيكون بأمر من الله مش عشان خاطر حد،\nوعلّمهم إنهم لو شافوا كسوف أو خسوف يصلوا ويتصدقوا ويدعوا ربنا ويستغفروا،\nوصلاة الكسوف مختلفة عن الصلاة العادية إللي بنصليها\n☆إزاي مختلفة\nشوفوا،\nالإمام يكبر تكبيرة الإحرام، وبعدين يقول دعاء الاستفتاح وبعدين يقول الاستعاذة، وبعدها يقرأ الفاتحة،\nوبعد الفاتحة يقرأ قراءة طويلة من القرآن،\n ممكن يقرأ سورة البقرة، أو البقرة وآل عمران، المهم القراءة تكون طويلة،\nوبعدها يركع ركوع طويل برده، وبعد ما يرفع من الركوع يقول سمع الله لمن حمده ، ربنا ولك الحمد،\nهنا بقى مش هينزل يسجد، لأ ده هيقول الفاتحة تاني ويقرأ قراءة طويلة تاني لكن تكون أقل من القراءة الأولى،\nيعني مثلا لو قرأ في المرة الأولى بالبقرة، يقرأ في المرة الثانية بآل عمران،\nلو قرأ في الأولى بثلاثة أجزاء يقرأ في القراءة الثانية بجزئين وهكذا،\nوبعد ما يخلص القراءة هيركع برده ركوع طويل لكن الركوع ده هيكون أقل في الطول من الركوع الأول،\nوبعد ما يرفع من الركوع الثاني ده هيقول سمع الله لمن حمده، ربنا ولك الحمد، وبعدين يسجد سجود طويل ويقوم يقعد بين السجدتين وبعدين يسجد تاني سجود طويل،\nوبعدها يقوم للركعة الثانية وهيعمل فيها نفس إللي عمله في الركعة الأولى لكن أقل في التطويل لحد ما يوصل للتشهد فيتشهد ويسلم\nوطبعا الكلام ينطبق على صلاة الخسوف\n☆طيب لو حد صلى صلاة الكسوف أو الخسوف زي صلاة التطوع العادية، ده ينفع ولّا لأ\nلو صلى الإنسان صلاة الكسوف أوالخسوف ركعتين كصلاة التطوع صلاته صحيحة وتُجزِئ، لكن السنة زي ما شرحنا كده والدليل على الكيفية دي في صلاة الكسوف هو حديث السيدة عائشة في البخاري ومسلم هتلاقوه في الروابط في التعليقات\n☆سؤال كمان:\nامتى وقت صلاة الكسوف\nصلاة الكسوف وقتها من بداية الكسوف لحد نهايته، ولو الناس خلصت صلاة قبل ما الكسوف يخلص فيكملوا الوقت ده بالتكبير والاستغفار والصدقة، \nومفيش دعاء معين رسول الله ﷺ أمر إننا ندعيه في الوقت ده، لكن استغفار ودعاء عادي، وهي صلاة جهرية،\nولو كان الكسوف جاء في وقت فيه نهي عن الصلاة زي بعد العصر مثلا يجوز نصليها عادي لأنها صلاة ذات سبب.\n◇إيه بقى الحكمة أصلا من صلاة الكسوف\nالحكمة هي تحقيق عبودية الخوف من الله تعالى،\nلأن رسول الله ﷺ قال:\n\"إن الشمس والقمر آيتان من آيات الله يخوّف الله بهما عباده\"\nمعنى الكلام إن الظاهرة دي المفروض تقذف الخوف في قلب المسلم فيفزع إلى الله بالصلاة والدعاء والتضرّع واللجوء إليه، \nوفي هنا إشارة وتنبيه للناس على قدرة الله وإنه قادر ينزل عليهم العذاب ويَسلُب منهم النّعم ويغير أحوالهم في لحظة زي ما غير الشمس والقمر لحالة همّ مش متعودين عليها،\nوكمان فيها تذكير بيوم القيامة وإللي هيحصل فيه من أمور غير طبيعية،\nربنا بيقول:\n《إِذَا الشَّمْسُ كُوِّرَتْ》\nويقول:\n《فَإِذَا بَرِقَ الْبَصَرُ * وَخَسَفَ الْقَمَرُ * وَجُمِعَ الشَّمْسُ وَالْقَمَرُ》\n☆ملحوظة:\nصلاة الخسوف سنة مؤكدة عن رسول الله ﷺ مش فرض يعني، ولو فات وقتها لا تُقضى\nدي كده كانت أهم المعلومات عن صلاة الكسوف، إن شاء الله تكون واضحة، \nمصادر جزء النهاردة في التعليقات"}, {"n": 246, "l": "الجزء 220 | سارق يعلم ابا هريره", "u": "https://www.facebook.com/groups/710210019782034/permalink/837717257031309/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وعشرين\n#أحداث_السنة_العاشرة_من_الهجرة\n#سارق_يعلم_أبا_هريرة\nمن الأحداث إللي حصلت في السنة العاشرة من الهجرة نزول آية:\n\"يَا أَيُّهَا الَّذِينَ آمَنُوا لِيَسْتَأْذِنكُمُ الَّذِينَ مَلَكَتْ أَيْمَانُكُمْ وَالَّذِينَ لَمْ يَبْلُغُوا الْحُلُمَ مِنكُمْ ثَلَاثَ مَرَّاتٍ\n مِن قَبْلِ صَلَاةِ الْفَجْرِ وَحِينَ تَضَعُونَ ثِيَابَكُم مِّنَ الظَّهِيرَةِ وَمِن بَعْدِ صَلَاةِ الْعِشَاء\n ثَلَاثُ عَوْرَاتٍ لَّكُمْ لَيْسَ عَلَيْكُمْ وَلَا عَلَيْهِمْ جُنَاحٌ بَعْدَهُنَّ طَوَّافُونَ عَلَيْكُم بَعْضُكُمْ عَلَى بَعْضٍ كَذَلِكَ يُبَيِّنُ اللَّهُ لَكُمُ الْآيَاتِ وَاللَّهُ عَلِيمٌ حَكِيمٌ\"\nوالآية بصفة عامة معناها:\nربنا بيأمر المؤمنين إللي صدّقوا بالله ورسوله ﷺ وأيقنوا بشريعته كنظام ومنهج لحياتهم إنهم يعلموا العبيد والإِماء والخدم والأطفال المُمَيّزِين إللي لسه لم يبلغوا مبلغ الرجال إنهم يستأذنوا قبل الدخول على الرجل وزوجته في ثلاث أوقات هم:\n◇قبل صلاة الفجر:\n لأنه وقت الاستيقاظ من النوم، وتغيير ملابس النوم وارتداء ثياب اليقظة، وفي هنا احتمال لانكشاف العورة.\n ◇وقت الظهيرة\n لأنه وقت خلع ثياب العمل، والاستعداد للنوم.\n◇من بعد صلاة العشاء:\nلأنه وقت خلع ثياب اليقظة، ولبس ثياب النوم.\n فالأوقات دي أوقات نوم وراحة وطبيعي إن الإنسان فيها  ممكن يتكشف وهو نايم ويظهر منه شيء ميحبش أنه يظهر،\nفخلوا عبيدَكم وخدمكم وصِبيانكم ميدخلوش عليكم غير لما يستأذنوا،\nأما في غير الأوقات دي؛ عادي ومفيش حرج إنهم يدخلوا من غير استئذان؛ لأنهم بيقوموا على خدمتكم واللهُ لا يكلِّفكم ما فيه حرجٌ أو ضِيق عليكم؛\nلأن تشريعه من أجل صالحكم، وهو جلَّ وعلا العليمُ الحكيم.\nوظاهر الأمر إللي في الآية إنه واجب، لكن جمهور العلماء قالوا إن الأمر هنا غرضه الاستحباب والتعليم والإرشاد إلى محاسن الآداب وليس للوجوب\n☆طيب إيه سبب نزول الآية أصلا\nالعلماء ذكروا كذا سبب لنزول الآية، قالوا منها:\n◇إن في صحابية اسمها أسماء بنت مَرثد دخل عليها غلام كبير فاشتكت الموضوع ده لرسول الله ﷺ،\nيعني هو دخل عليها من غير استئذان فلما اشتكت لرسول الله ﷺ نزلت الآية دي.\n◇وقالوا:\nإن رسول الله ﷺ أرسل غلام من الأنصار لعمر بن الخطاب رضي الله عنه في وقت الظهيرة عشان يدعوه لرسول الله ﷺ،\nفلما الغلام راح لعمر لقاه نايم وكان قافل عليه الباب، فالغلام دق على الباب ونادى على عمر وراح داخل عليه وهو نايم،\nفاستيقظ عمر من نومه وقعد فانكشف منه شيء،\nفقال عمر:\n\"وددت أن الله تعالى نهى أبناءنا ونساءنا وخدمنا عن الدخول علينا في هذه الساعات إلا بالإذن\"\nيعني عايز إن ربنا ينزل قرآن يمنع فيه الدخول في الأوقات دي إلا بإذن، \nوبعد كده توجه عمر لرسول الله ﷺ، فلقى إن ربنا أنزل الآية دي، فسجد لله شكرا،\nوالعلماء بيقولوا إن الآية دي من مُوافقات عمر رضي الله عنه للقرآن، زي آية الحجاب كده.\nفممكن بسبب وقوع أكثر من حادثة في نفس الوقت بقى للآية أكثر من سبب نزول\nمن الأحداث المهمة جدا إللي حصلت في السنة العاشرة من الهجرة خروج رسول الله ﷺ لأداء الحج، ولأن رسول الله ﷺ لم يحج غير حجة واحدة فقط وبعدها مات فالحجة دي اتسمت حجة الوداع،\nلكن قبل ما نعرف تفاصيل أحداث الحج، هنتكلم عن بعض قصص الصحابة مع رسول الله ﷺ؛ \nلأن بعد ما نتكلم عن حجة الوداع هيبقى باقي بعض الأحداث وبعدها رسول الله ﷺ هيموت\nفقبل ما ندخل في النهاية خلونا نستمتع شوية بصحبة رسول الله ﷺ من خلال بعض الأحداث إللي حصلت مع الصحابة\n♡أول موقف معانا هو موقف أبو هريرة مع السارق\nبيحكي أبو هريرة ويقول:\nوَكَّلَنِي رَسُولُ اللَّهِ ﷺ بِحِفْظِ زَكَاةِ رَمَضَانَ، فَأَتَانِي آتٍ فَجَعَلَ يَحْثُو مِنَ الطَّعَامِ فَأَخَذْتُهُ، وَقُلْتُ: \nوَاللَّهِ لَأَرْفَعَنَّكَ إِلَى رَسُولِ اللَّهِ ﷺ\nيعني بيقول إن رسول الله ﷺ أعطى له مهمة حراسة زكاة الفطر، واحنا عارفين إن زكاة الفطر بتكون حبوب من قوت أهل البلد،\nفكانت الزكاة متجمعة في مكان وأبو هريرة هو المسؤول عن حراستها،\nفجاء رجل وقعد ياخد من الزكاة بإيده ويعبي منها، فلما شافه أبو هريرة مسكه وقال له أنا هوديك لرسول الله ﷺ وهو يتصرف معاك،\nفالرجل قال له:\nإنِّي محتاجٌ وعليَّ عيالٌ ولي حاجةٌ شديدةٌ\nفزي ما تقولوا كده أبو هريرة أشفق عليه وسابه يمشي\nتاني يوم الصبح اتقابل أبو هريرة مع رسول الله ﷺ عادي في الصلاة، فرسول الله ﷺ سأل أبا هريرة:\nيا أبَا هُرَيْرَةَ، ما فَعَلَ أسِيرُكَ البَارِحَةَ؟\nيعني عملت إيه مع الرجل إللي انت مسكته امبارح؟\nفقال له أبو هريرة:\nشَكا حاجةً شديدةً وعيالًا ، فرَحِمْتُهُ وخلَّيتُ سبيلَهُ.\nيعني اشتكى إنه محتاج وعنده عيال فأشفقت عليه وسيبته يمشي، \nهنا رسول الله ﷺ قال له:\n\" أما إنَّهُ قد كذبَكَ ، وسيعودُ\"\nيعني هو كذب عليك وهيجيلك تاني، فعرف أبو هريرة إن الرجل ده هييجي بسبب كلام رسول الله ﷺ، \nوأكيد رسول الله ﷺ عرف إللي حصل عن طريق الوحي\nفأبو هريرة قعد له بقى يستناه\nففعلا جاء الرجل زي ما رسول الله ﷺ قال وقعد ياخد من الزكاة، فمسكه أبو هريرة وقال له:\nلأرفعنَّكَ إلى رسولِ اللَّهِ ﷺ\nفالرجل قال له: \nدَعني فإنِّي مُحتاجٌ وعليَّ عيالٌ لا أعودُ\nيعني سيبني، خلاص مش هعمل كده تاني، أنا عندي عيال ومحتاج، فأشفق عليه أبو هريرة وسابه،\nتاني يوم الصبح قابل رسول الله ﷺ فسأله رسول الله ﷺ:\nيا أبا هُرَيْرةَ، ما فعلَ أسيرُكَ البارحةَ؟\nفقال أبو هريرة:\nيا رسولَ اللَّهِ، شَكا حاجةً وعيالًا، فرَحِمْتُهُ فخلَّيتُ سبيلَهُ.\nفقال له رسول الله ﷺ:\nأما إنَّهُ قد كذبَكَ وسيعودُ\nفقعد أبو هريرة يراقب المكان تاني ويستناه، فلقاه فعلا جاي وعمّال يعبي من الزكاة،\nفمسكه أبو هريرة للمرة الثالثة وقال له:\nلأرفعنَّكَ إلى رسولِ اللَّهِ ﷺ وهذا آخِرُ ثلاثِ مرَّاتٍ أنَّكَ تزعمُ أنَّكَ لا تعودُ ثمَّ تعودُ\nيعني خلاص أنا هوديك لرسول الله ﷺ وهو يتصرف معاك\nوانسى إني أصدقك تاني، تقولي خلاص مش هعمل كده تاني وترجع تعمل برده،\nفالرجل قال لأبي هريرة:\nدعني أعلِّمْكَ كلماتٍ ينفعُكَ اللَّهُ بِها\nفقال له أبو هريرة:\n ما هنَّ ؟\nفقال له الرجل:\n\"إذا أويتَ إلى فراشِكَ فاقرأ آيةَ الكرسيِّ اللَّهُ لَا إِلَهَ إلَّا هُوَ الْحَيُّ القَيُّومُ حتَّى تختمَ الآيةَ، فإنَّك لَن يزالَ عليكَ منَ اللَّهِ حافظٌ ، ولا يقربُكَ شيطانٌ حتَّى تُصْبِحَ\"\nيعني لما تيجي تنام خلاص اقرأ آية الكرسي، لو عملت كده ربنا هيحفظك ومفيش أي شيطان هيقدر يقرب منك لحد ما تصحى\nفتركه أبو هريرة بعد ما الرجل قال له الكلام ده، وكان الصحابة رضي الله عنهم هم أحرص الناس على الخير، فشاف أبو هريرة إن دي صفقة رابحة، \nفعلمه الكلمات مقابل إنه يطلق سراحه،\nتاني يوم الصبح قابل أبو هريرة رسول الله ﷺ، فسأله رسول الله ﷺ تاني:\n ما فعلَ أسيرُكَ البارحةَ ؟ \nفحكى له أبو هريرة إللي حصل، قال:\n\"يا رسولَ اللَّهِ، زعمَ أنَّهُ يعلِّمُني كلماتٍ ينفعُني اللَّهُ بِها فخلَّيتُ سبيلَهُ\"\nفسأله رسول الله ﷺ عن الكلمات دي فقال له أبو هريرة:\n\" قالَ لي:\nإذا أويتَ إلى فراشِكَ فاقرأ آيةَ الكرسيِّ من أوَّلِها حتَّى تختمَ الآية اللَّهُ لَا إِلَهَ إلَّا هُوَ الْحَيُّ القَيُّومُ وقالَ لي: \nلن يزالَ عليكَ منَ اللَّهِ حافظٌ ولا يقربُكَ شَّيطانٌ حتَّى تُصْبِحَ ، فقالَ النَّبيُّ ﷺ:\nأما إنَّهُ صدَقكَ وهو كذوبٌ، تعلَمُ من تخاطبُ ثلاثَ ليالٍ، يا أبا هُرَيْرةَ ؟\nيعني هو كاذب في العموم لكن المعلومة إللي قالها لك دي فعلا صحيحة ويقرها الإسلام،\nوبعدين رسول الله ﷺ سأله بقى إذا كان يعرف حقيقة الشخص إللي كلمه ده أو لأ،\nفقال أبو هريرة: لا ، فقالَ له رسول الله ﷺ: ذاكَ شَيطانٌ\nيعني الرجل إللي انت شوفته ده ومسكته وقعدت كلمته كان شيطان متمثل في هيئة رجل.\n☆ملحوظة عشان أفكركم، قلنا قبل كده في الجزء الستين إن إللي بيتسلسل في رمضان هم مَردة الجن فقط، يعني الجن الأقوياء إللي لهم تأثير قوي على الإنسان،\nيعني مش كل الشياطين بتكون متسليلة بدليل القصة إللي قلناها دلوقتي دي، وإنها حصلت في رمضان، وحديث أبو هريرة ده موجود في البخاري\n◇سؤال بقى:\nالشيطان عرف إزاي المعلومة دي وأبو هريرة معرفهاش\nأبو هريرة رضي الله عنه إسلامه كان متأخر، أسلم في السنة السابعة من الهجرة، وسورة البقرة إللي فيها آية الكرسي كانت أول سورة نزلت بعد الهجرة للمدينة،\nوآية الكرسي لها فضل كبير أخبره رسول الله ﷺ للصحابة،\nزي إن إللي بيقرأ آية الكرسي بعد كل صلاة لا يمنعه من دخول الجنة إلا الموت،\nوأبو هريرة مكنش لسه متعلم كل العلم فالمعلومة دي مكنش لسه عرفها،\nوطبيعي طبعا إن الجن مسلمهم وكافرهم يعرفوا المعلومات دي؛ لأنهم بيشوفوا الصحابة وبيشوفوا رسول الله ﷺ وبيسمعوا كلامهم وبيشوفوا أفعالهم من غير ما الصحابة ولا رسول الله ﷺ يشوفوهم، إلا طبعا في حالات معينة مش موضوعنا دلوقتي،\nالمهم إن الشيطان ده كان عارف المعلومة فعشان ينجو من أبي هريرة قاله المعلومة دي ورسول الله ﷺ أكد له المعلومة\n☆وهنا رسول الله ﷺ بيعلمنا درس مهم\nوهو إن ممكن توصل لنا المعلومة الصحيحة عن طريق إنسان فاجر أو فاسق أو حتى كافر،\nفمش معنى إن الشخص إللي نقل لنا المعلومة الصحيحة سيء مثلا يبقى نرد الحق إللي جاء على لسانه، \nاحنا ممكن نتأكد من المعلومة ماشي، لكن مش نقول أنا مش هاخد المعلومة من فلان وأنا عارف إنه على حق لمجرد إن ده فلان الفلاني،\nرسول الله ﷺ وضح لأبي هريرة إن على الرغم من إن ده شيطان كافر لكن المعلومة إللي قالها صحيحة ونصحه بيها،\nوده مثال على إن:\nالفاجر قد يَعلم الحق فلا يتّبعه ولا ينتفع به، فيتلقّاه المؤمن منه فيجد فيه الخير الكثير\nيبقى من القصة دي نعرف إن الجن ممكن يتمثلوا في صورة بشر، زي ما اتكلمنا في الجزء مائة وتسعة وستين عن خالد بن الوليد رضي الله عنه لما راح قتل العُزى وكانت عبارة شيطانة متمثلة في صورة امرأة،\nفالبشر يقدروا يشوفوا الجن وهم متمثلين في صورة بشر أو حيوانات زي الأفعى والكلب والأسود وغيرها، أو ممكن يتمثلوا في أشكال غريبة برده،\nلكن البشر ميقدروش يشوفوا الجن على صورتهم الحقيقية إللي ربنا خلقهم عليها، ما عدا طبعا رسول الله ﷺ وإخوانه من الأنبياء يقدروا يشوفوهم،\nوالدليل على كده قول ربنا:\n\"إِنَّهُ يَرَاكُمْ هُوَ وَقَبِيلُهُ مِنْ حَيْثُ لا تَرَوْنَهُمْ\"\nفربنا أعطى الجن القدرة على إنهم يغيروا شكلهم، قال شيخ الإسلام ابن تيمية في مجموع الفتاوى:\n\"والجن يتصورون في صور الإنس والبهائم ، فيتصورون في صور الحيات والعقارب وغيرها ، \nوفي صور الإبل والبقر والغنم والخيل والبغال والحمير ، وفي صور الطير ، وفي صور بني آدم\"\nوزي مانتم شوفتوا شياطين الجن تعرف الحقّ وتجحده ولا تتبعه زي شياطين الإنس بالضبط\nإن شاء الله المرة الجاية هنكمل بعض مواقف رسول الله ﷺ مع الصحابة\nمصادر جزء النهاردة في التعليقات"}, {"n": 247, "l": "الجزء 221 | صاحب القبر المنفرد", "u": "https://www.facebook.com/groups/710210019782034/permalink/837719350364433/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وواحد_وعشرين\n#أحداث_السنة_العاشرة_من_الهجرة\n#صاحب_القبر_المُنفرِد\nهنكمل الكلام إن شاء الله عن بعض قصص الصحابة مع رسول الله ﷺ،\nواحد من الصحابة اسمه أبو موسى الأشعري اتوضى في بيته وبعدين خرج وهو ناوي إنه يلازم رسول الله ﷺ ويكون معاه طول اليوم،\nوأبو موسى الأشعري ده أصله من اليمن، واسمه عبدُ اللهِ بنُ قَيْس، \nلما سمع أبو موسى بخروج رسول الله ﷺ في بداية البعثة؛ آمن به وهو في مكة لما كان موجود هناك للتجارة،\nو بعدين توجه أبو موسى لليمن يدعو قومه فآمن معه إخوته، وكان هو أصغر واحد فيهم، وآمن قومه بعدين،\nووصفهم رسول الله ﷺ بأنهم أرق الناس قلوبا،\nخرج أبو موسى الأشعري من اليمن ومعاه إخواته الاتنين،\nفركبوا سفينة فوصلتهم للحبشة، فتقابل أبو موسى مع جعفر بن أبي طالب رضي الله عنه وقال جعفر لأبي موسى إن رسول الله ﷺ أمرهم إنهم يُقيموا في الحبشة،\nفقعد أبو موسى في الحبشة هو وإخوته، \nوبعدين رجع للمدينة مع باقي المسلمين إللي كانوا في الحبشة بقيادة جعفر بن أبي طالب رضي الله عنه مع فتح خيبر، لما رسول الله ﷺ قال:\n\"ما أدري بأيّهما أنا أُسَر: بفتح خيبر، أم بقدوم جعفر\"\nزي ما شرحنا في الجزء المائة وتسعة وثلاثون،\nقال عنه رسول الله ﷺ:\n\"سيّد الفوارِس أبو موسى\"\nوكان صوت أبو موسى رضي الله عنه جميل جدا في القرآن، وفي مرة كان بيقرأ القرآن بالليل في بيته فعدى عليه رسول الله ﷺ وسمعه وهو بيقرأ، فقعد رسول الله ﷺ يستمع لصوته وهو بيقرأ وأبو موسى ميعرفش،\nتاني يوم لما رسول الله ﷺ قابل أبو موسى قال له رسول الله ﷺ:\n\"لو رأيتني وأنا أستمع قراءتك البارحة\"\nيعني أنا كنت بسمعك وانت بتقرأ القرآن امبارح وكنت مبسوط ومستمتع بقراءتك،\nفقال له أبو موسى:\n\"أما إني لَوْ عَلِمْتُ بمكانك لَحَبَّرْتُهُ تَحْبيرًا\"\nيعني لو أنا كنت أعرف إنك بتسمع لقراءتي كنت جمّلت وحسّنت صوتي أكثر وأكثر عشان تستمتع بالقراءة،\nوتحسين الصوت يكون بحُسْنِ الأداءِ، \nبِحيث يُبَيِّنُ الحُروفَ ويُخْرِجُها من مَخارِجِها، حتَّى يبدُوَ القرآن ُواضحًا ظاهرا، \nويكونُ بحُسنِ النَّغَمَةِ بحيث يحقق المَقصود مِنَ الخَشْيةِ والخُشوعِ والتَّفهُّمِ\nزي كده لما بنسمع قارئ للقرآن بيبقى صوته جميل وتجويده ممتاز وبنحس بالخشية والخشوع وهو بيقرأ\nوقال رسول الله ﷺ لأبي موسى الأشعري:\n\"لقد أوتيتَ مزمارًا من مزاميرِ آل داوُد\"\nومزامير آل داود المقصود بها صوته الحسن، \nونفس صوت الإنسان يُسمى مزمار،\nوآل داود المقصود بيها داود عليه السلام نفسه،\nفرسول الله ﷺ شبَّه حُسنَ صوت أبي موسى بما أعطاه الله لداود عليه السلام من حُسْن صوت، \nمش المقصود التشبيه بآلة المزمار المعروفة، عشان بس محدش يفهم غلط ويستدل من كلام رسول الله ﷺ إن المزمار حلال زي ما بعض ضِعاف العلم قالوا\n☆ملحوظة:\nعقيدة الأشاعرة المعروفة لا تُنسب إلى الصحابي أبو موسى الأشعري، ولكنها تُنسب إلى واحد اسمه أبو الحسن الأشعري من علماء القرن الثالث الهجري،\n وهو ينتهي نسبه إلى أبو موسى الأشعري رضي الله عنه،\nوأبو الحسن الأشعري في آخر حياته تراجع عن عقيدة الأشاعرة دي زي ما قال بعض أهل العلم زي ابن كثير رحمه الله،\nوالتزم بعقيدة أهل السنة والجماعة إللي هي ما عليه رسول الله ﷺ والصحابة.\nكده احنا خدنا فكرة عامة عن أبي موسى رضي الله عنه، نرجع بقى ونشوف أبو موسى عمل إيه مع رسول الله ﷺ بعد ما خرج من بيته وهو ناوي يلازم رسول الله ﷺ طول اليوم،\nخرج أبو موسى وتوجه للمسجد، \nلما وصل ملقاش رسول الله ﷺ في المسجد، سأل الصحابة إللي كانوا في المسجد عنه قالوا له:\n\"خَرَجَ ووَجَّهَ هَا هُنَا\"\nيعني قالوا له إنه خرج واتجه ناحية كذا وشاوروا له على الاتجاه إللي توجه له رسول الله ﷺ، قال أبو موسى:\n\"فَخَرَجْتُ علَى إثْرِهِ أسْأَلُ عنْه حتَّى دَخَلَ بئْرَ أرِيسٍ\"\nيعني أبو موسى خرج من المسجد وتتبع أثر رسول الله ﷺ وسأل عنه الناس لحد ما عرف إنه دخل بئر أَرِيس، وهو بُستانٌ معروف بِالقُربِ مِن قُباء،\nفقعد أبو موسى عند باب البستان، وكان الباب مصنوع من جريد النخل، \nانتظر أبو موسى رضي الله عنه عند الباب لحد ما رسول الله ﷺ قضى حاجته وتوضأ وبعدها دخل أبو موسى البستان، \nفلقى رسول الله ﷺ \"جَالِسٌ علَى بئْرِ أرِيسٍ وتَوَسَّطَ قُفَّهَا، وكَشَفَ عن سَاقَيْهِ ودَلَّاهُما في البِئْرِ\"\nيعني لقى رسول الله ﷺ قاعد على الجزء المرتفع إللي بيكون حول البئر، وكاشف عن ساقه ومنزلهم في البئر،\nفسلم أبو موسى على رسول الله ﷺ، وقرر في نفسه إنه يقعد عند الباب ويكون بواب رسول الله ﷺ، يعني مش هيخلي حد يدخل على رسول الله ﷺ إلا لما يستأذن،\nفهنا رسول الله ﷺ:\n\"يا أبا موسى أملك عليّ الباب، فلا يدخلن عليّ أحد إلا بإذن\"\nيعني رسول الله ﷺ قال لأبي موسى إنه يكون بواب له وميدخّلش حد إلا بإذن،\nفوافق أمر رسول الله ﷺ رغبة أبي موسى إنه يكون بواب رسول الله ﷺ\n☆ملحوظة هنا:\nرسول الله ﷺ في الأصل مكنش عنده بواب ولا حاجب يحجب الناس عنه، \nلكن في مواقف طارئة كان رسول الله ﷺ بيتخذ بواب لسبب أو لآخر،\nزي ما حصل كده لما رسول الله ﷺ اعتزل نساؤه وكان الغلام إللي اسمه رباح واقف بواب على الحجرة إللي كان رسول الله ﷺ معتزل فيها، \nوجاء عمر وطلب الاستئذان للدخول على رسول الله ﷺ، زي ما شرحنا في الجزء مائتين واثنين،\nفهنا برده ده من المواقف المعدودة إللي رسول الله ﷺ اتخذ فيها بواب،\nقعد أبو موسى عند الباب، فلقى الباب بيتحرك وبيطلب الإذن بالدخول، \nفسأل أبو موسى عن اسم الشخص الداخل، فقال إنه أبو بكر، فطلب منه أبو موسى إنه يستنى وميدخلش،\nفتوقف أبو بكر مكانه وراح أبو موسى لرسول الله ﷺ يقوله إن أبا بكر جاء وبيطلب الإذن بالدخول،\nفقال له رسول الله ﷺ:\n\"ائْذَنْ له وبَشِّرْهُ بالجَنَّةِ\"\nيعني خليه يدخل وبشره إنه من أهل الجنة، فرجع أبو موسى لأبي بكر الصديق رضي الله عنه وقال له:\n\" ادْخُلْ، ورَسولُ اللَّهِ ﷺ يُبَشِّرُكَ بالجَنَّةِ\"\nفدخل أبو بكر وقعد يحمد ربنا على البُشرى دي لحد ما راح جلس على يمين رسول الله ﷺ،\nوكشف عن ساقه ووضعها داخل البئر، زي وضع رسول الله ﷺ بالضبط\nقعد أبو موسى عند الباب وهو بيفكر وبيقول:\n\"إنْ يُرِدِ اللَّهُ بفُلَانٍ خَيْرًا يَأْتِ به\"\nيعني هو يقصد أخوه؛ لأنه كان سابه بيتوضى وقاله إنه يلحق به بعد ما يخلص، فبيقول إنه لو نصيب إنه يُبشّر بالجنة ربنا هيخليه ييجي،\nوهو بيفكر كده لقى إنْسَانٌ يُحَرِّكُ البَابَ، فَقُال: \nمَن هذا؟\nفَقَالَ: عُمَرُ بنُ الخَطَّابِ، \nفَقال أبو موسى: علَى رِسْلِكَ\nيعني استنى لحد ما استأذن لك رسول الله ﷺ، فراح أبو موسى لرسول الله ﷺ فسلم عليه وقال:\nهذا عُمَرُ بنُ الخَطَّابِ يَسْتَأْذِنُ؟\nفَقَالَ رسول الله ﷺ: ائْذَنْ له وبَشِّرْهُ بالجَنَّةِ.\nفرجع أبو موسى لعمر رضي الله عنه وقال له:\nادْخُلْ، وبَشَّرَكَ رَسولُ اللَّهِ ﷺ بالجَنَّةِ،\nفَدَخَلَ عمر فَجَلَسَ مع رَسولِ اللَّهِ ﷺ عن يَسَارِهِ، ووضع رِجْلَيْهِ في البِئْرِ، زي رسول الله ﷺ وزي أبو بكر،\nرجع أبو موسى لمكانه وهو بيقول في نفسه:\n\"إنْ يُرِدِ اللَّهُ بفُلَانٍ خَيْرًا يَأْتِ به\"\nبيتكلم عن أخوه برده، عايز أخوه ييجي عشان رسول الله ﷺ يبشره بالجنة هو كمان\nوهو قاعد جَاءَ إنْسَانٌ يُحَرِّكُ البَابَ، فَقُال أبو موسى: مَن هذا؟ فَقَالَ: عُثْمَانُ بنُ عَفَّانَ.\nفَقُال أبو موسى: علَى رِسْلِكَ\nفَجاء أبو موسى لرَسولِ اللَّهِ ﷺ فأخْبَرهُ، فَقَالَ:\nائْذَنْ له وبَشِّرْهُ بالجَنَّةِ، علَى بَلْوَى تُصِيبُهُ\nيعني خليه يدخل وبشّره بالجنة لكن هيحصل له ابتلاء شديد في الدنيا قبل ما يموت ويدخل الجنة،\nفرجع أبو موسى لعثمان رضي الله عنه وقال له:\n\"ادْخُلْ، وبَشَّرَكَ رَسولُ اللَّهِ ﷺ بالجَنَّةِ علَى بَلْوَى تُصِيبُكَ\"\nفقال عثمان بن عفان رضي الله عنه:\n\"اللهم صبرا، أو الله المستعان\"\n☆ملحوظة:\nالمقصود بالبلوى إللي رسول الله ﷺ قال إنها هتحصل هي إللي حصل لعثمان رضي الله عنه في آخر خلافته من الشهادة يوم الدار، وثوران المنافقين عليه،\nوطبعا الكلام ده من معجزات رسول الله ﷺ، لأنه أخبر عن الغيب، يعني حاجة هتحصل بعد سنين من موته ﷺ\nوالكلام عن بلوى عثمان رضي الله عنه يطول شرحه فهنتكلم عنه إن شاء الله بالتفصيل واحنا بنتكلم عن الخلفاء إذا ربنا أحيانا\nدخل عثمان رضي الله عنه فلقى الناحية إللي رسول الله ﷺ قاعد فيها اتملت ومفيش مكان له فراح قعد في الجهة المقابلة لرسول الله ﷺ.\nواحد من التابعين الكبار إللي عنده علم واسع اسمه سعيد بن المُسيّب قال عن الموقف ده:\n\"فأوَّلْتُهَا قُبُورَهُمْ\"\nيعني هو فسّر جلوس رسول الله ﷺ واجتماعه مع أبو بكر وعمر في ناحية واحدة بإن ده اجتماعهم مع بعض في قبر واحد،\nلأن زي ماحنا عارفين إن رسول الله ﷺ مدفون معاه في قبره أبو بكر وعمر رضي الله عنهما،\nوالوحيد إللي انفرد عنهم هو عثمان رضي الله عنه لما قعد لوحده في الجهة المقابلة، وكان عثمان رضي الله عنه دُفن في البقيع، فكده يبقى هو صاحب القبر المُنفرد\nاحنا اتكلمنا قبل كده عن بعض القصص إللي رسول الله ﷺ كان بيحكيها للصحابة من وقت للتاني،\nفمن القصص إللي حكاها رسول الله ﷺ قصة رجل اشترى  مِن رَجُلٍ عَقارًا له، \nفَوَجَدَ الرَّجُلُ الذي اشْتَرَى العَقارَ في عَقارِهِ جَرَّةً فيها ذَهَبٌ، فقالَ له الذي اشْتَرَى العَقارَ: \nخُذْ ذَهَبَكَ مِنِّي، إنَّما اشْتَرَيْتُ مِنْكَ الأرْضَ، ولَمْ أبْتَعْ مِنْكَ الذَّهَبَ،\nوقالَ الذي له الأرْضُ:\nإنَّما بعْتُكَ الأرْضَ وما فيها، فَتَحاكما إلى رَجُلٍ، \nفقالَ الذي تَحاكما إلَيْهِ: ألَكُما ولَدٌ؟ \nقالَ أحَدُهُما: لي غُلامٌ، \nوقالَ الآخَرُ: لي جارِيَةٌ، \nقالَ: أنْكِحُوا الغُلامَ الجارِيَةَ وأَنْفِقُوا علَى أنْفُسِهِما منه وتَصَدَّقا\"\nالمعنى إن رجل اشترى من رجل زي قطعة أرض كده، فالمُشتري لقى جرة ذهب في الأرض يعني وعاء فيه ذهب،\nفرجع للرجل إللي اشترى منه الأرض وقال له خد الذهب بتاعك، أنا اشتريت الأرض بس مشترتش الذهب إللي فيها،\nفالراجل إللي باع الأرض قال له وأنا بعت لك الأرض باللي فيها، فكده جرة الذهب دي بقت بتاعتك\nفكل واحد بقى مصمم على رأيه،\nفبحثوا عن واحد تالت يحكم بينهم، وحكوا له الموضوع،\nفسألهم الرجل إللي بيحكم بينهم إذا كان عندهم أبناء أو لأ، فواحد قال انا عندي ولد والتاني قال أنا عندي بنت،\nفقال لهم خلاص جوزوا الولد للبنت وجهزوهم من الفلوس دي، وكمان تصدقوا ويبقى كده المشكلة اتحلت\nفالرجل إللي حكم بينهم ده شاف إن المال في حُكم المال الضائع إللي ملوش صاحب، والرجلين دول هم أحق الناس بالمال،\nولما شاف ورعهما وحُسن حالِهما شاف إن نسلهم هيبقى ذرية طيبة فاقترح الاقتراح ده،\nوإلا كان ممكن يقسم المال بينهم نصين كحل من الحلول يعني، \nفالقصة دي حكاها رسول الله ﷺ للصحابة عشان يعلمهم الوَرَع\nومن معاني الورع:\nاجتناب الشبهات خوفاً من الوقوع في المحرمات. \nزي مثلا الخروج عن خلاف العلماء بحسب الإمكان،\nيعني لو اختلف العلماء في شيء هل هو مُباح أم حرام فالورع إننا نترك الشيء ده،\nأو لو اختلفوا فيه هل هو مباح أو واجب فالورع هنا إننا نعمل الفعل ده مع الاعتقاد إنه واجب\nوطول ما الإنسان عايش بالوَرع عمره ما هيقع في الحرام\nإن شاء الله المرة الجاية هنكمل الكلام عن بعض القصص إللي رسول الله ﷺ حكاها للصحابة\nمصادر جزء النهاردة في التعليقات"}]);
